1	// sc4sap:program-to-spec — Screen mockup renderer (SVG → PNG)
2	//
3	// PURPOSE
4	//   Produce PNG images of Selection Screen and ALV layout for the
5	//   "Inputs & Screens" sheet of a generated spec xlsx. Replaces the older
6	//   cell-border wireframe approach (v5..v7) with embedded images.
7	//
8	// PUBLIC API
9	//   renderSelectionScreenSVG({ fields, blockLabels? })       → svg string
10	//   renderAlvLayoutSVG({ columns, sampleRows, maxRows=3 })   → svg string
11	//   rasterizeSvgToPng(svg, { width, height })                → Promise<Buffer|null>
12	//   renderScreenImages(spec)                                 → Promise<{selection,alv}|null>
13	//
14	// TOKEN ECONOMY (MANDATORY — propagated from SKILL.md)
15	//   · ALV sample rows capped at 3 (configurable up to 5).
16	//   · Minimal SVG: no gradients, no shadows, no emoji glyph payloads.
17	//   · Drop SVG/PNG temp files after rasterization (tmp folder auto-cleaned).
18	//
19	// FALLBACK POLICY
20	//   rasterizeSvgToPng returns null when no headless browser is available
21	//   (Edge/Chrome/Chromium not on PATH, or spawn error). Callers must
22	//   degrade to the legacy cell-border wireframe helpers in
23	//   rich-xlsx-template.mjs (screenFrameRow/screenSubtitleRow/screenMerge)
24	//   so spec generation never crashes on CI without Chrome.
25	
26	import { spawn, spawnSync } from 'node:child_process';
27	import { writeFileSync, readFileSync, mkdtempSync, rmSync, existsSync } from 'node:fs';
28	import { tmpdir, platform } from 'node:os';
29	import { join } from 'node:path';
30	import { inflateSync, deflateSync } from 'node:zlib';
31	
32	// ──────────────────────────────────────────────────────────────
33	// SVG templates — minimal, no gradients
34	// ──────────────────────────────────────────────────────────────
35	
36	function xml(s) {
37	  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;')
38	    .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
39	}
40	
41	// ──────────────────────────────────────────────────────────────
42	// Localized legend strings (auto-derived per spec).
43	// Extended by adding a new `lang` key; missing keys fall back to 'ko'.
44	// ──────────────────────────────────────────────────────────────
45	const LEGEND = {
46	  ko: {
47	    required:       '필수 입력',
48	    dropdown:       '▼ 복수 선택',
49	    range:          '~ 범위(LOW~HIGH)',
50	    status_done:    '완료',
51	    status_partial: '부분입고',
52	    status_open:    '미입고',
53	    hotspot_text:   '밑줄 파랑',
54	    hotspot_label:  'Hotspot (더블클릭 이동)',
55	    editable_cell:  '노랑 셀',
56	    editable_label: '편집 가능',
57	  },
58	  en: {
59	    required:       'Required',
60	    dropdown:       '▼ Multi-select',
61	    range:          '~ Range (LOW~HIGH)',
62	    status_done:    'Done',
63	    status_partial: 'Partial',
64	    status_open:    'Open',
65	    hotspot_text:   'Blue underline',
66	    hotspot_label:  '= Hotspot (click to navigate)',
67	    editable_cell:  'Yellow cell',
68	    editable_label: '= Editable',
69	  },
70	  ja: {
71	    required:       '必須入力',
72	    dropdown:       '▼ 複数選択',
73	    range:          '~ 範囲(LOW~HIGH)',
74	    status_done:    '完了',
75	    status_partial: '一部入荷',
76	    status_open:    '未入荷',
77	    hotspot_text:   '青下線',
78	    hotspot_label:  '= Hotspot (ダブルクリックで遷移)',
79	    editable_cell:  '黄色セル',
80	    editable_label: '= 編集可能',
81	  },
82	};
83	function legendFor(lang) { return LEGEND[lang] || LEGEND.ko; }
84	
85	// Approximate pixel width of a text string at 12 px font.
86	// Conservative estimate: ASCII ≈ 7 px, CJK/full-width ≈ 13 px.
87	// Used to lay out the selection-screen label column dynamically so that
88	// long English labels (e.g. "Distribution Channel (S_VTWEG)") don't run
89	// underneath the input boxes — the previous fixed inputX=200 truncated
90	// anything wider than 162 px.
91	function approxTextWidthPx(s) {
92	  let w = 0;
93	  for (const ch of String(s ?? '')) {
94	    w += (ch.charCodeAt(0) > 0x7F ? 13 : 7);
95	  }
96	  return w;
97	}
98	
99	/**
100	 * fields: [{
101	 *   required?: boolean,
102	 *   label: string,             e.g. '구매조직'
103	 *   name: string,              e.g. 'S_EKORG'
104	 *   range?: boolean,           true → LOW ~ HIGH two inputs
105	 *   note?: string,
106	 * }, ...]
107	 *
108	 * NOTE: `defaultLow` / `defaultHigh` are ACCEPTED in the field schema for
109	 *  spec documentation (they show up in the Parameters table), but they are
110	 *  NOT rendered inside the input-box graphic any more. The field name is
111	 *  already labeled next to the box; stuffing "BOM" / "1000" / "오늘" inside
112	 *  the input box just adds visual noise. Callers can still pass these
113	 *  values — the renderer silently ignores them.
114	 *
115	 * `lang` controls the bottom legend text ('ko' | 'en' | 'ja').
116	 */
117	export function renderSelectionScreenSVG({
118	  fields = [],
119	  blockLabel = '조회 조건',
120	  optionFields = [],
121	  optionBlockLabel = '옵션',
122	  lang = 'ko',
123	} = {}) {
124	  const L = legendFor(lang);
125	  const rowH = 24;
126	  const padTop = 40, padBottom = 60, optionBlockH = optionFields.length ? 24 + optionFields.length * rowH : 0;
127	
128	  // ── Dynamic label-column layout ───────────────────────────────
129	  // Compute the label column's pixel width from the actual longest
130	  // label across BOTH the main block and the option block, then push
131	  // every input-box x-coord right of that so labels never overlap the
132	  // inputs. Minimum inputX stays at 200 to preserve the legacy look
133	  // for short CJK labels (typical 구매조직 (S_EKORG) ≈ 135 px).
134	  const LABEL_X = 38;
135	  const LABEL_GAP = 16;            // gap between label end and input start
136	  const BOX_W = 150;
137	  const SEP_GAP = 8;
138	  const allLabels = [
139	    ...fields.map(f => `${f.label} (${f.name})`),
140	    ...optionFields.map(f => `${f.label} (${f.name})`),
141	  ];
142	  const maxLabelPx = allLabels.length ? Math.max(...allLabels.map(approxTextWidthPx)) : 150;
143	  const inputX = Math.max(200, LABEL_X + maxLabelPx + LABEL_GAP);
144	  const sepX   = inputX + BOX_W + SEP_GAP;              // '~' center
145	  const highX  = sepX + 10;                              // HIGH box left
146	  const rangeDropX = highX + BOX_W + 2;                  // range dropdown
147	  const singleDropX = inputX + BOX_W + 2;                // single dropdown
148	  const rangeNoteX = rangeDropX + 28;
149	  const singleNoteX = singleDropX + 28;
150	  // Trailing note text can be up to ~200 px wide; block frame + 10 margin.
151	  const noteReserve = 200;
152	  const w = Math.max(900, rangeNoteX + noteReserve);
153	  const h = padTop + fields.length * rowH + padBottom + optionBlockH + 60;
154	
155	  const rows = fields.map((f, i) => {
156	    const y = padTop + (i + 1) * rowH - 6;
157	    const star = f.required ? `<text x="25" y="${y}" fill="#B00020" font-weight="700">*</text>` : '';
158	    const label = `<text x="${LABEL_X}" y="${y}">${xml(f.label)} (${xml(f.name)})</text>`;
159	    if (f.range) {
160	      return [
161	        star, label,
162	        `<rect x="${inputX}" y="${y - 12}" width="${BOX_W}" height="16" fill="#FFF" stroke="#808080"/>`,
163	        `<text x="${sepX}" y="${y}" text-anchor="middle">~</text>`,
164	        `<rect x="${highX}" y="${y - 12}" width="${BOX_W}" height="16" fill="#FFF" stroke="#808080"/>`,
165	        `<rect x="${rangeDropX}" y="${y - 12}" width="16" height="16" fill="#EEE" stroke="#808080"/><text x="${rangeDropX + 8}" y="${y}" text-anchor="middle">▼</text>`,
166	        f.note ? `<text x="${rangeNoteX}" y="${y}" fill="#666">${xml(f.note)}</text>` : '',
167	      ].join('');
168	    }
169	    return [
170	      star, label,
171	      `<rect x="${inputX}" y="${y - 12}" width="${BOX_W}" height="16" fill="#FFF" stroke="#808080"/>`,
172	      `<rect x="${singleDropX}" y="${y - 12}" width="16" height="16" fill="#EEE" stroke="#808080"/><text x="${singleDropX + 8}" y="${y}" text-anchor="middle">▼</text>`,
173	      f.note ? `<text x="${singleNoteX}" y="${y}" fill="#666">${xml(f.note)}</text>` : '',
174	    ].join('');
175	  }).join('');
176	
177	  const blockTop = 20;
178	  const blockH = padTop + fields.length * rowH + 20;
179	  const optBlockY = blockTop + blockH + 20;
180	
181	  const optionRows = optionFields.map((f, i) => {
182	    const y = optBlockY + 34 + i * rowH;
183	    return [
184	      `<rect x="${inputX}" y="${y - 10}" width="12" height="12" fill="#FFF" stroke="#555"/>`,
185	      `<text x="${inputX + 20}" y="${y}">${xml(f.label)} (${xml(f.name)})</text>`,
186	      f.note ? `<text x="${inputX + 220}" y="${y}" fill="#666">${xml(f.note)}</text>` : '',
187	    ].join('');
188	  }).join('');
189	
190	  const legendY = optBlockY + optionBlockH + 30;
191	
192	  // Dynamic legend — only emit items that actually apply to this spec.
193	  // (No required fields → omit *; no ranges → omit ~; empty field set →
194	  // omit legend entirely.)
195	  const allFields = [...fields, ...optionFields];
196	  const legendParts = [];
197	  if (allFields.some(f => f.required)) legendParts.push(`<tspan fill="#B00020" font-weight="700">*</tspan> ${xml(L.required)}`);
198	  if (fields.length) legendParts.push(xml(L.dropdown));
199	  if (fields.some(f => f.range)) legendParts.push(xml(L.range));
200	  const legendSvg = legendParts.length
201	    ? `<text x="25" y="${legendY}" fill="#555" font-size="11">${legendParts.join(' · ')}</text>`
202	    : '';
203	
204	  return `<?xml version="1.0" encoding="UTF-8"?>
205	<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" font-family="Arial,sans-serif" font-size="12">
206	<rect width="${w}" height="${h}" fill="#FFF"/>
207	<rect x="10" y="${blockTop}" width="${w - 20}" height="${blockH}" fill="none" stroke="#7E9CC2"/>
208	<rect x="30" y="${blockTop - 8}" width="${Math.max(120, approxTextWidthPx(blockLabel) + 40)}" height="16" fill="#FFF"/>
209	<text x="36" y="${blockTop + 5}" font-weight="700" fill="#0A4F8C">◆ ${xml(blockLabel)}</text>
210	${rows}
211	${optionFields.length ? `
212	<rect x="10" y="${optBlockY}" width="${w - 20}" height="${optionBlockH}" fill="none" stroke="#7E9CC2"/>
213	<rect x="30" y="${optBlockY - 8}" width="${Math.max(70, approxTextWidthPx(optionBlockLabel) + 40)}" height="16" fill="#FFF"/>
214	<text x="36" y="${optBlockY + 5}" font-weight="700" fill="#0A4F8C">◆ ${xml(optionBlockLabel)}</text>
215	${optionRows}
216	` : ''}
217	${legendSvg}
218	</svg>`;
219	}
220	
221	/**
222	 * Compute final SVG dimensions for a selection-screen spec — matches the
223	 * internal math of renderSelectionScreenSVG so renderScreenImages() can
224	 * allocate the headless browser viewport without duplicating formulas.
225	 */
226	export function selectionScreenMetrics({ fields = [], optionFields = [] } = {}) {
227	  const rowH = 24;
228	  const padTop = 40, padBottom = 60;
229	  const optionBlockH = optionFields.length ? 24 + optionFields.length * rowH : 0;
230	  const h = padTop + fields.length * rowH + padBottom + optionBlockH + 60;
231	  const LABEL_X = 38, LABEL_GAP = 16, BOX_W = 150, SEP_GAP = 8;
232	  const allLabels = [
233	    ...fields.map(f => `${f.label} (${f.name})`),
234	    ...optionFields.map(f => `${f.label} (${f.name})`),
235	  ];
236	  const maxLabelPx = allLabels.length ? Math.max(...allLabels.map(approxTextWidthPx)) : 150;
237	  const inputX = Math.max(200, LABEL_X + maxLabelPx + LABEL_GAP);
238	  const rangeNoteX = inputX + BOX_W + SEP_GAP + 10 + BOX_W + 2 + 28;
239	  const w = Math.max(900, rangeNoteX + 200);
240	  return { width: w, height: h };
241	}
242	
243	/**
244	 * columns: [{ name, header, width?, align?: 'left'|'center'|'end', hotspot?, editable? }]
245	 * sampleRows: [{ [colName]: value, _status?: '●'|'○'|'◉', _locked?: boolean }]
246	 *
247	 * `lang` controls the bottom legend text ('ko' | 'en' | 'ja'). The legend
248	 * items are also **auto-derived** from the actual spec — if no column has
249	 * `hotspot: true`, the Hotspot item is omitted; if no column has
250	 * `editable: true`, the Editable item is omitted; if no `_status` column
251	 * exists (and no sampleRow sets `_status`), the traffic-light items are
252	 * omitted. When nothing applies, the legend row is skipped entirely and
253	 * the SVG height shrinks by ~30 px. This stops the renderer from telling
254	 * readers that a program has features it does not actually have.
255	 */
256	export function renderAlvLayoutSVG({ columns = [], sampleRows = [], maxRows = 3, lang = 'ko' } = {}) {
257	  const L = legendFor(lang);
258	  const rows = sampleRows.slice(0, Math.max(1, Math.min(maxRows, 5)));
259	  const totalW = columns.reduce((s, c) => s + (c.width || 100), 0) + 20;
260	  const w = Math.max(900, Math.min(totalW, 1600));
261	  const rowH = 24;
262	  const headerH = 22;
263	  // Spec-driven legend feature detection — only include items that apply.
264	  const hasStatus   = columns.some(c => c.name === '_status') || rows.some(r => r && r._status);
265	  const hasHotspot  = columns.some(c => c.hotspot);
266	  const hasEditable = columns.some(c => c.editable);
267	  const hasLegend   = hasStatus || hasHotspot || hasEditable;
268	  const legendPad   = hasLegend ? 80 : 30;
269	  const h = 10 + headerH + rows.length * rowH + legendPad;
270	
271	  let x = 10;
272	  const colX = columns.map(c => { const left = x; x += (c.width || 100); return left; });
273	  const gridRight = x;
274	
275	  const headerCells = columns.map((c, i) => {
276	    const cx = colX[i] + (c.width || 100) / 2;
277	    return `<text x="${cx}" y="${10 + headerH - 7}" text-anchor="middle" font-weight="700" fill="#0A4F8C">${xml(c.header || c.name)}</text>`;
278	  }).join('');
279	
280	  const sepLines = colX.slice(1).map(lx =>
281	    `<line x1="${lx}" y1="10" x2="${lx}" y2="${10 + headerH + rows.length * rowH}" stroke="#C8D4E2"/>`).join('');
282	
283	  const dataRows = rows.map((r, rIdx) => {
284	    const y = 10 + headerH + rIdx * rowH;
285	    const bg = r._locked ? '#F0F5FA' : (rIdx % 2 === 1 ? '#F5F9FC' : '#FFF');
286	    const bandBg = rIdx % 2 === 1 || r._locked
287	      ? `<rect x="10" y="${y}" width="${gridRight - 10}" height="${rowH}" fill="${bg}"/>` : '';
288	    const cells = columns.map((c, ci) => {
289	      const cx = colX[ci] + (c.width || 100) / 2;
290	      const leftX = colX[ci] + 8, rightX = colX[ci] + (c.width || 100) - 8;
291	      const cy = y + rowH - 8;
292	      const val = r[c.name];
293	      const statusFill = { '●': '#D4A017', '○': '#C0392B', '◉': '#1E8449' };
294	      if (c.name === '_status' || c.editable) {
295	        if (c.editable) {
296	          const editBg = r._locked ? '#E5E5E5' : '#FFF6C8';
297	          const editStroke = r._locked ? '#999' : '#A67F25';
298	          return `<rect x="${colX[ci] + 2}" y="${y + 3}" width="${(c.width || 100) - 4}" height="${rowH - 6}" fill="${editBg}" stroke="${editStroke}"/>`
299	            + (val !== undefined ? `<text x="${rightX}" y="${cy}" text-anchor="end" font-family="monospace" fill="${r._locked ? '#888' : '#000'}">${xml(val)}</text>` : '');
300	        }
301	      }
302	      if (val === undefined || val === null || val === '') return '';
303	      const strVal = String(val);
304	      if (c.name === '_status') {
305	        return `<text x="${cx}" y="${cy}" text-anchor="middle" fill="${statusFill[strVal] || '#555'}" font-weight="700">${xml(strVal)}</text>`;
306	      }
307	      if (c.hotspot) {
308	        return `<text x="${cx}" y="${cy}" text-anchor="middle" font-family="monospace" fill="#1F5AA0" text-decoration="underline">${xml(strVal)}</text>`;
309	      }
310	      const anchor = c.align === 'end' ? 'end' : (c.align === 'left' ? 'start' : 'middle');
311	      const tx = anchor === 'end' ? rightX : anchor === 'start' ? leftX : cx;
312	      const fam = /^[\d.,\-]+$/.test(strVal) ? 'monospace' : 'Arial,sans-serif';
313	      return `<text x="${tx}" y="${cy}" text-anchor="${anchor}" font-family="${fam}">${xml(strVal)}</text>`;
314	    }).join('');
315	    return bandBg + cells;
316	  }).join('');
317	
318	  const legendY = 10 + headerH + rows.length * rowH + 30;
319	
320	  const legendParts = [];
321	  if (hasStatus) {
322	    legendParts.push(
323	      `<tspan fill="#1E8449" font-weight="700">◉</tspan> ${xml(L.status_done)}`,
324	      `<tspan fill="#D4A017" font-weight="700">●</tspan> ${xml(L.status_partial)}`,
325	      `<tspan fill="#C0392B" font-weight="700">○</tspan> ${xml(L.status_open)}`,
326	    );
327	  }
328	  if (hasHotspot)  legendParts.push(`<tspan fill="#1F5AA0" text-decoration="underline">${xml(L.hotspot_text)}</tspan> ${xml(L.hotspot_label)}`);
329	  if (hasEditable) legendParts.push(`<tspan>${xml(L.editable_cell)}</tspan> ${xml(L.editable_label)}`);
330	  const legendSvg = hasLegend
331	    ? `<text x="10" y="${legendY}" font-size="11" fill="#555">${legendParts.join(' · ')}</text>`
332	    : '';
333	
334	  return `<?xml version="1.0" encoding="UTF-8"?>
335	<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" font-family="Arial,sans-serif" font-size="12">
336	<rect width="${w}" height="${h}" fill="#FFF"/>
337	<rect x="10" y="10" width="${gridRight - 10}" height="${headerH}" fill="#D0DEED" stroke="#3E7DB3"/>
338	${headerCells}
339	${dataRows}
340	<rect x="10" y="10" width="${gridRight - 10}" height="${headerH + rows.length * rowH}" fill="none" stroke="#C8D4E2"/>
341	${sepLines}
342	${legendSvg}
343	</svg>`;
344	}
345	
346	/**
347	 * ALV layout dimensions — mirrors the formulas in renderAlvLayoutSVG so
348	 * callers (renderScreenImages) can size the headless browser viewport
349	 * without duplicating the feature-detection logic.
350	 */
351	export function alvLayoutMetrics({ columns = [], sampleRows = [], maxRows = 3 } = {}) {
352	  const rows = sampleRows.slice(0, Math.max(1, Math.min(maxRows, 5)));
353	  const totalW = columns.reduce((s, c) => s + (c.width || 100), 0) + 20;
354	  const w = Math.max(900, Math.min(totalW, 1600));
355	  const hasStatus   = columns.some(c => c.name === '_status') || rows.some(r => r && r._status);
356	  const hasHotspot  = columns.some(c => c.hotspot);
357	  const hasEditable = columns.some(c => c.editable);
358	  const legendPad   = (hasStatus || hasHotspot || hasEditable) ? 80 : 30;
359	  const h = 10 + 22 + rows.length * 24 + legendPad;
360	  return { width: w, height: h };

