612	export async function rasterizeSvgToPng(svg, { width, height } = {}) {
613	  const browser = findBrowser();
614	  if (!browser) return null;
615	  const dir = mkdtempSync(join(tmpdir(), 'sc4sap-svg-'));
616	  try {
617	    const htmlPath = join(dir, 'in.html');
618	    const pngPath = join(dir, 'out.png');
619	    // INLINE the SVG into the HTML body (rather than <img src="in.svg">)
620	    // so the browser paints it synchronously with the initial parse. This
621	    // eliminates a load-vs-paint race that could also clip the output.
622	    const svgInline = String(svg).replace(/^<\?xml[^?]*\?>\s*/, '');
623	    writeFileSync(
624	      htmlPath,
625	      `<!doctype html><html><head><meta charset="utf-8">`
626	        + `<style>html,body{margin:0;padding:0;background:#fff}svg{display:block}</style>`
627	        + `</head><body>${svgInline}</body></html>`,
628	      'utf8',
629	    );
630	    const fileUrl = 'file:///' + htmlPath.replace(/\\/g, '/');
631	    const winW = width + CHROME_W_SLACK;
632	    const winH = height + CHROME_H_SLACK;
633	    // Async spawn — allows the caller to Promise.all() multiple rasterize jobs
634	    // in parallel (selection + ALV) so two headless browsers run concurrently.
635	    await new Promise((resolve, reject) => {
636	      const child = spawn(browser, [
637	        '--headless', '--disable-gpu', '--hide-scrollbars',
638	        // Pin DPR=1 so --window-size pixels map 1:1 to the screenshot
639	        // regardless of the host's Windows display scaling (125 % / 150 %).
640	        '--force-device-scale-factor=1',
641	        '--default-background-color=FFFFFFFF',
642	        `--screenshot=${pngPath}`,
643	        `--window-size=${winW},${winH}`,
644	        fileUrl,
645	      ], { windowsHide: true, stdio: 'ignore' });
646	      const timer = setTimeout(() => {
647	        try { child.kill('SIGKILL'); } catch { /* ignore */ }
648	        reject(new Error('headless browser timeout (30s)'));
649	      }, 30000);
650	      child.once('exit', (code) => {
651	        clearTimeout(timer);
652	        if (code === 0) resolve();
653	        else reject(new Error(`headless browser exited with code ${code}`));
654	      });
655	      child.once('error', (err) => {
656	        clearTimeout(timer);
657	        reject(err);
658	      });
659	    });
660	    if (!existsSync(pngPath)) return null;
661	    const padded = readFileSync(pngPath);
662	    // Crop off the chrome-slack padding so callers get an exact W × H PNG.
663	    try {
664	      return cropPngTopLeft(padded, width, height);
665	    } catch {
666	      // On any unexpected PNG shape, fall back to the padded buffer rather
667	      // than losing the render entirely — oversized but visually complete.
668	      return padded;
669	    }
670	  } catch {
671	    return null;
672	  } finally {
673	    try { rmSync(dir, { recursive: true, force: true }); } catch { /* ignore */ }
674	  }
675	}
