677	/**
678	 * Convenience — render both screens from a spec dict.
679	 * spec: { selection: { fields, optionFields, ... }, alv: { columns, sampleRows, maxRows? }, lang? }
680	 * Returns { selection: { pngBuffer, width, height } | null, alv: { ... } | null }.
681	 * Null values signal the caller to fall back to cell-border wireframes.
682	 *
683	 * `lang` is forwarded to both sub-renderers so the auto-derived legends
684	 * come out in the spec's language. When absent it defaults to 'ko' inside
685	 * the renderers, preserving backward-compatible behaviour.
686	 */
687	export async function renderScreenImages({ selection, alv, lang = 'ko' } = {}) {
688	  const out = { selection: null, alv: null };
689	  // PARALLEL RENDERING — selection + ALV rasterize concurrently.
690	  // Each rasterizeSvgToPng() spawns its own headless browser process, so
691	  // Promise.all() cuts wall-clock time roughly in half (~3s → ~3s instead
692	  // of ~6s on Windows/Edge). Each task is self-contained: a rasterize
693	  // failure or timeout in one does not affect the other — the output of
694	  // the failed branch simply stays null and the caller falls back to the
695	  // cell-border wireframe for that section only.
696	  const tasks = [];
697	  if (selection) {
698	    tasks.push((async () => {
699	      try {
700	        const svg = renderSelectionScreenSVG({ ...selection, lang });
701	        // Use the shared metrics helper so we stay in lockstep with the
702	        // renderer's actual layout — avoids the bug where a longer label
703	        // widened the SVG but the viewport stayed at 900 and cropped it.
704	        const { width, height } = selectionScreenMetrics(selection);
705	        const png = await rasterizeSvgToPng(svg, { width, height });
706	        if (png) out.selection = { pngBuffer: png, width, height };
707	      } catch { /* keep selection null → wireframe fallback */ }
708	    })());
709	  }
710	  if (alv) {
711	    tasks.push((async () => {
712	      try {
713	        // v10: when `panes` is supplied we route to the multipane composer
714	        // (Split-ALV / Tabstrip / Sequence). Otherwise the legacy single-grid
715	        // path renders unchanged. The shape detection happens here, not at
716	        // the driver level, so existing per-spec drivers keep working as-is.
717	        const isMultipane = Array.isArray(alv.panes) && alv.panes.length > 0;
718	        const svg = isMultipane
719	          ? renderMultipaneAlvSVG({ ...alv, lang })
720	          : renderAlvLayoutSVG({ ...alv, lang });
721	        const { width, height } = isMultipane
722	          ? multipaneAlvMetrics(alv)
723	          : alvLayoutMetrics(alv);
724	        const png = await rasterizeSvgToPng(svg, { width, height });
725	        if (png) out.alv = { pngBuffer: png, width, height };
726	      } catch { /* keep alv null → wireframe fallback */ }
727	    })());
728	  }
729	  await Promise.all(tasks);
730	  return out;
731	}
