323	<xdr:blipFill><a:blip r:embed="${img.rid}"/><a:stretch><a:fillRect/></a:stretch></xdr:blipFill>
324	<xdr:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="${cx}" cy="${cy}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></xdr:spPr>
325	</xdr:pic>
326	<xdr:clientData/>
327	</xdr:oneCellAnchor>`;
328	  }).join('');
329	  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
330	<xdr:wsDr xmlns:xdr="http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
