874	// Selection-screen wireframe, rendered as cell-border rows. Column layout
875	// matches workflow-steps.md "Selection-screen parameter-row alignment":
876	//   B:E label (style 7) · F:H low (style 6) · I ▼ (style 0)
877	//   J ~ (style 7, range only) · K:M high (style 6, range only)
878	//   N ▼ (range only) · O:P note (style 0)
879	function renderSelectionWireframe(cells, merges, rowHeights, startRow, spec) {
880	  const fields = spec.fields || [];
881	  const optionFields = spec.optionFields || [];
882	  const blockLabel = spec.blockLabel || '조회 조건';
883	  let r = startRow;
884	
885	  // Block title bar — grey, all borders (style 17).
886	  screenFullRow(cells, merges, r, `◆ ${blockLabel}`, 17);
887	  rowHeights[r] = 20;
888	  r++;
889	
890	  for (const f of fields) {
891	    screenFrameRow(cells, r);  // col A / Q frame continuity
892	    const prefix = f.required ? '* ' : '  ';
893	    const label = `${prefix}${f.label || ''} (${f.name || ''})`;
894	    screenMerge(cells, merges, r, 1, 4, 7, label);                     // B:E label
895	    screenMerge(cells, merges, r, 5, 7, 6, f.defaultLow || '');        // F:H low input (sky blue)
896	    cells[R(r - 1, 8)] = { v: '▼', s: 0 };                             // I dropdown
897	    if (f.range) {
898	      cells[R(r - 1, 9)] = { v: '~', s: 7 };                           // J range separator
899	      screenMerge(cells, merges, r, 10, 12, 6, f.defaultHigh || '');   // K:M high input
900	      cells[R(r - 1, 13)] = { v: '▼', s: 0 };                          // N dropdown
901	    }
902	    screenMerge(cells, merges, r, 14, 15, 0, f.note || '');            // O:P note
903	    rowHeights[r] = 18;
904	    r++;
905	  }
906	
907	  // Optional checkbox block (if present).
908	  if (optionFields.length) {
909	    screenSubtitleRow(cells, merges, r, `◆ ${spec.optionBlockLabel || '옵션'}`, 17);
910	    r++;
911	    for (const f of optionFields) {
912	      screenFrameRow(cells, r);
913	      screenMerge(cells, merges, r, 1, 4, 7, `☐ ${f.label || ''} (${f.name || ''})`);
914	      screenMerge(cells, merges, r, 5, 15, 0, f.note || '');
915	      rowHeights[r] = 18;
916	      r++;
917	    }
918	  }
919	
920	  screenCloseFrame(cells, r);
921	  return r + 1;
922	}
