function openInDefault(p) {
  let cmd, args;
  if (platform() === 'win32') { cmd = 'cmd.exe'; args = ['/c', 'start', '""', p]; }
  else if (platform() === 'darwin') { cmd = 'open'; args = [p]; }
  else { cmd = 'xdg-open'; args = [p]; }
  const child = spawn(cmd, args, { detached: true, stdio: 'ignore', shell: false });
  child.unref();
}

