// screensSheet
// =============================================================
function screensSheet({ hasSelectionImg = false, hasAlvImg = false, alvStartRow = 19, paramsStartRow = 49 } = {}) {
  const cells = {}, merges = [];
  const cols = [
    { min: 1,  max: 1,  width: 3     },
    { min: 2,  max: 5,  width: 14    },
    { min: 6,  max: 6,  width: 50.71 },
