// =============================================================
function sanitizeSheetName(name, seenNames) {
  let n = String(name ?? '').replace(/[\\/?*\[\]]/g, '-').replace(/^'+|'+$/g, '');
  if (n.length > 31) n = n.slice(0, 31);
  if (!n) n = 'Sheet';
  let candidate = n, i = 2;
  while (seenNames.has(candidate)) { const suf = ` (${i})`; candidate = n.slice(0, 31 - suf.length) + suf; i++; }
