    { name: `xl/drawings/drawing${d.drawingId}.xml`, data: Buffer.from(drawingXml(d.imgs), 'utf8') },
    { name: `xl/drawings/_rels/drawing${d.drawingId}.xml.rels`, data: Buffer.from(drawingRelsXml(d.imgs), 'utf8') },
