// =============================================================
async function buildImages() {
  if (!SELECTION_IMAGE_SPEC && !ALV_IMAGE_SPEC) return [];
  try {
    const hereDir = dirname(fileURLToPath(import.meta.url));
    const candidates = [join(hereDir, 'screen-image-renderer.mjs')];
    let cur = hereDir;
    for (let i = 0; i < 8; i++) {
      candidates.push(join(cur, 'scripts', 'spec', 'screen-image-renderer.mjs'));
      candidates.push(join(cur, 'sc4sap', 'scripts', 'spec', 'screen-image-renderer.mjs'));
      const parent = dirname(cur);
      if (parent === cur) break;
      cur = parent;
    }
    candidates.push(join(process.cwd(), 'scripts', 'spec', 'screen-image-renderer.mjs'));
    if (process.env.CLAUDE_PLUGIN_ROOT) candidates.push(join(process.env.CLAUDE_PLUGIN_ROOT, 'scripts', 'spec', 'screen-image-renderer.mjs'));
    const rendererPath = candidates.find(p => existsSync(p));
    if (!rendererPath) { console.warn('[screen-images] renderer not found — using wireframe'); return []; }
    const { renderScreenImages } = await import(pathToFileURL(rendererPath).href);
    const imgs = await renderScreenImages({ selection: SELECTION_IMAGE_SPEC, alv: ALV_IMAGE_SPEC, lang: SPEC_LANG });
    const out = [];
    if (imgs.selection) out.push({ sheetName: INPUTS_SHEET_NAME, anchorCell: 'B3',  pngBuffer: imgs.selection.pngBuffer, width: imgs.selection.width, height: imgs.selection.height });
