    return out;
  } catch (err) {
    console.warn('[screen-images] error:', err?.message || err, '— using wireframe');
    return [];
  }
}

const images = await buildImages();
build(OUT_PATH, { images });
openInDefault(OUT_PATH);

// =============================================================
// Self-cleanup
// =============================================================
const CLEANUP_AFTER_BUILD = true;
if (CLEANUP_AFTER_BUILD && existsSync(OUT_PATH)) {
  try {
    const selfPath = fileURLToPath(import.meta.url);
    unlinkSync(selfPath);
