// =============================================================
// textSheet
// =============================================================
function visualWidth(s) {
  let w = 0;
  for (const ch of String(s ?? '')) {
    const cp = ch.codePointAt(0);
    if ((cp >= 0x1100 && cp <= 0x11FF) || (cp >= 0x2E80 && cp <= 0x303F) ||
        (cp >= 0x3040 && cp <= 0x30FF) || (cp >= 0x3400 && cp <= 0x9FFF) ||
        (cp >= 0xAC00 && cp <= 0xD7AF) || (cp >= 0xF900 && cp <= 0xFAFF) ||
        (cp >= 0xFF00 && cp <= 0xFFEF) || cp >= 0x1F000) { w += 2; } else { w += 1; }
  }
  return w;
}
const WIDTH_PADDING = 6, WIDTH_MIN = 12, WIDTH_MAX = 100, WRAP_THRESHOLD = 55;
const LINE_HEIGHT_PT = 16.875, HEADER_ROW_HEIGHT = 22.5, WARNING_ROW_HEIGHT = 22.5, MAX_ROW_HEIGHT = 300;
const HEIGHT_BY_LINES = { 2: 33.75, 3: 51, 4: 67.5 };
function rowHeightForLines(n) { return HEIGHT_BY_LINES[n] ?? Math.min(n * LINE_HEIGHT_PT, MAX_ROW_HEIGHT); }

function textSheet(rows, opts = {}) {
  const cells = {}, rowHeights = {};
  const maxCols = Math.max(...rows.map(r => r.length));
  const explicitWidths = Array.isArray(opts.colWidths) ? opts.colWidths : null;
  const autoCols = [];
  for (let c = 0; c < maxCols; c++) {
    let maxVw = 0;
    for (const row of rows) { const vw = visualWidth(row[c] ?? ''); maxVw = Math.max(maxVw, Math.min(vw, WRAP_THRESHOLD)); }
    autoCols.push({ min: c + 1, max: c + 1, width: Math.min(Math.max(maxVw + WIDTH_PADDING, WIDTH_MIN), WIDTH_MAX) });
  }
  let cols;
  if (explicitWidths) {
    cols = [];
    let i = 0;
    while (i < explicitWidths.length) {
      const w = explicitWidths[i]; let j = i;
      while (j + 1 < explicitWidths.length && explicitWidths[j + 1] === w) j++;
      cols.push({ min: i + 1, max: j + 1, width: w }); i = j + 1;
    }
    if (explicitWidths.length < maxCols) cols.push({ min: explicitWidths.length + 1, max: maxCols, width: WIDTH_MIN });
  } else { cols = autoCols; }
  if (rows.length > 0) rowHeights[1] = HEADER_ROW_HEIGHT;
  rows.forEach((row, rIdx) => {
    let maxLines = 1, anyLong = false;
    row.forEach((val, cIdx) => {
      const ref = R(rIdx, cIdx);
      const vw = visualWidth(val);
      const usable = Math.max(1, (autoCols[cIdx]?.width ?? WIDTH_MIN) - WIDTH_PADDING);
      const isLong = vw > WRAP_THRESHOLD;
      const style = rIdx === 0 ? (isLong ? 24 : 4) : (isLong ? 23 : 18);
      cells[ref] = { v: val, s: style };
      if (isLong) { anyLong = true; const lines = Math.ceil(vw / usable); if (lines > maxLines) maxLines = lines; }
    });
    if (rIdx > 0 && anyLong) { rowHeights[rIdx + 1] = rowHeightForLines(Math.max(2, maxLines)); }
  });
  return { cells, merges: [], cols, rowHeights };
}

function appendProcessFlow(payload, items, opts = {}) {
  if (!Array.isArray(items) || items.length === 0) return payload;
  const { cells, merges, rowHeights, cols } = payload;
  const heading = opts.heading || '프로세스 플로우 차트';
  const colSpan = Math.max(1, Math.min(3, cols.length || 3));
  const lastCol = colLetter(colSpan - 1);
  let maxRow = 0;
  for (const ref of Object.keys(cells)) { const m = /^([A-Z]+)(\d+)$/.exec(ref); if (m) maxRow = Math.max(maxRow, +m[2]); }
  let r = maxRow + 2;
  cells[R(r - 1, 0)] = { v: heading, s: 17 };
  for (let c = 1; c < colSpan; c++) cells[R(r - 1, c)] = { s: 17 };
  if (colSpan > 1) merges.push(`A${r}:${lastCol}${r}`);
  rowHeights[r] = 22; r++;
  items.forEach((raw, idx) => {
    const txt = String(raw ?? '');
    const isDecision = /^\?\s*/.test(txt), isTerminal = /^!\s*/.test(txt);
    const label = isDecision ? `◇ ${txt.replace(/^\?\s*/, '')}` : isTerminal ? `■ ${txt.replace(/^!\s*/, '')}` : txt;
    const style = isDecision ? 20 : 21;
    cells[R(r - 1, 0)] = { v: label, s: style };
    for (let c = 1; c < colSpan; c++) cells[R(r - 1, c)] = { s: style };
    if (colSpan > 1) merges.push(`A${r}:${lastCol}${r}`);
    rowHeights[r] = 24; r++;
    if (idx < items.length - 1) {
      cells[R(r - 1, 0)] = { v: '↓', s: 25 };
      for (let c = 1; c < colSpan; c++) cells[R(r - 1, c)] = { s: 25 };
      if (colSpan > 1) merges.push(`A${r}:${lastCol}${r}`);
      rowHeights[r] = 16; r++;
    }
  });
  return payload;
}

// =============================================================
// screensSheet helpers
// =============================================================
function screenFrameRow(cells, row) { cells[R(row - 1, 0)] = { s: 9 }; cells[R(row - 1, 16)] = { s: 10 }; }
function screenCloseFrame(cells, row) {
  cells[R(row - 1, 0)] = { s: 15 };
  for (let c = 1; c <= 15; c++) cells[R(row - 1, c)] = { s: 12 };
  cells[R(row - 1, 16)] = { s: 16 };
}
function screenFullRow(cells, merges, row, val, s) {
  cells[R(row - 1, 0)] = { v: val, s };
  for (let c = 1; c <= 16; c++) cells[R(row - 1, c)] = { s };
  merges.push(`A${row}:Q${row}`);
}
function screenSubtitleRow(cells, merges, row, val, s = 1) {
  cells[R(row - 1, 0)] = { s: 9 }; cells[R(row - 1, 1)] = { v: val, s };
  for (let c = 2; c <= 15; c++) cells[R(row - 1, c)] = { s };
  cells[R(row - 1, 16)] = { s: 10 };
  merges.push(`B${row}:P${row}`);
}
function screenMerge(cells, merges, row, c0, c1, style, value) {
  cells[R(row - 1, c0)] = { v: value ?? '', s: style };
  for (let c = c0 + 1; c <= c1; c++) cells[R(row - 1, c)] = { s: style };
  if (c1 > c0) merges.push(`${colLetter(c0)}${row}:${colLetter(c1)}${row}`);
}

function paramsBlock(cells, merges, rowHeights, startRow, params = []) {
  const COLS = [[1, 3], [4, 5], [6, 7], [8, 10], [11, 15]];
  const HEADERS = ['필드', '타입', '필수', '기본값', '설명'];
  let r = startRow;
  cells[R(r - 1, 0)] = { v: '파라미터', s: 17 };
  for (let c = 1; c <= 16; c++) cells[R(r - 1, c)] = { s: 17 };
  merges.push(`A${r}:Q${r}`); rowHeights[r] = 20; r++;
  cells[R(r - 1, 0)] = { s: 9 };
  HEADERS.forEach((h, i) => {
    const [c0, c1] = COLS[i];
    cells[R(r - 1, c0)] = { v: h, s: 4 };
    for (let c = c0 + 1; c <= c1; c++) cells[R(r - 1, c)] = { s: 4 };
    merges.push(`${colLetter(c0)}${r}:${colLetter(c1)}${r}`);
  });
  cells[R(r - 1, 16)] = { s: 10 }; r++;
  for (const p of params) {
    cells[R(r - 1, 0)] = { s: 9 };
    const vals = [p.field, p.type, p.required, p.defaultVal, p.description];
    vals.forEach((v, i) => {
      const [c0, c1] = COLS[i];
      cells[R(r - 1, c0)] = { v: v ?? '', s: 5 };
      for (let c = c0 + 1; c <= c1; c++) cells[R(r - 1, c)] = { s: 5 };
      merges.push(`${colLetter(c0)}${r}:${colLetter(c1)}${r}`);
    });
    cells[R(r - 1, 16)] = { s: 10 }; r++;
  }
  return r;
}

function renderSelectionWireframe(cells, merges, rowHeights, startRow, spec) {
  const fields = spec.fields || [], optionFields = spec.optionFields || [];
  let r = startRow;
  screenFullRow(cells, merges, r, `◆ ${spec.blockLabel || '조회 조건'}`, 17); rowHeights[r] = 20; r++;
  for (const f of fields) {
    screenFrameRow(cells, r);
    screenMerge(cells, merges, r, 1, 4, 7, `${f.required ? '* ' : '  '}${f.label || ''} (${f.name || ''})`);
    screenMerge(cells, merges, r, 5, 7, 6, '');
    cells[R(r - 1, 8)] = { v: '▼', s: 0 };
    if (f.range) { cells[R(r - 1, 9)] = { v: '~', s: 7 }; screenMerge(cells, merges, r, 10, 12, 6, ''); cells[R(r - 1, 13)] = { v: '▼', s: 0 }; }
    screenMerge(cells, merges, r, 14, 15, 0, f.note || '');
    rowHeights[r] = 18; r++;
  }
  screenCloseFrame(cells, r); return r + 1;
}

function distributeAlvColumns(n) {
  if (n <= 0) return [];
  const base = Math.floor(15 / n), extra = 15 - base * n;
  const out = []; let c = 1;
  for (let i = 0; i < n; i++) { const w = base + (i < extra ? 1 : 0); out.push([c, c + w - 1]); c += w; }
  return out;
}

function renderAlvWireframe(cells, merges, rowHeights, startRow, spec) {
  const columns = spec.columns || (spec.panes ? spec.panes[1]?.columns || [] : []);
  const sampleRows = (spec.sampleRows || (spec.panes ? spec.panes[1]?.sampleRows || [] : [])).slice(0, 3);
  let r = startRow;
  screenFullRow(cells, merges, r, '◆ ALV 그리드 (우측 — CL_GUI_ALV_GRID)', 17); rowHeights[r] = 20; r++;
  const layout = distributeAlvColumns(columns.length);
  if (!layout.length) { screenCloseFrame(cells, r); return r + 1; }
  screenFrameRow(cells, r);
  columns.forEach((c, i) => { const [c0, c1] = layout[i]; screenMerge(cells, merges, r, c0, c1, 4, c.header || c.name || ''); });
  rowHeights[r] = 20; r++;
  for (const row of sampleRows) {
    screenFrameRow(cells, r);
    columns.forEach((c, i) => { const [c0, c1] = layout[i]; screenMerge(cells, merges, r, c0, c1, 5, String(row[c.name] ?? '')); });
    rowHeights[r] = 18; r++;
  }
  screenCloseFrame(cells, r); return r + 1;
}

