function sheetXml({cells,merges=[],cols=[],rowHeights={}}){const grouped=new Map();for(const[ref,c]of Object.entries(cells)){const m=ref.match(/^([A-Z]+)(\d+)$/);const rowIdx=+m[2];if(!grouped.has(rowIdx))grouped.set(rowIdx,[]);grouped.get(rowIdx).push({ref,...c});}const rowXmls=[];for(const rowIdx of[...grouped.keys()].sort((a,b)=>a-b)){const cs=grouped.get(rowIdx).sort((a,b)=>a.ref.localeCompare(b.ref,undefined,{numeric:true}));const ht=rowHeights[rowIdx]?` ht="${rowHeights[rowIdx]}" customHeight="1"`:'';const cellXmls=cs.map(c=>{const hasStyle=(c.s!==undefined&&c.s!==null);const styleAttr=hasStyle?` s="${c.s}"`:'';const isEmpty=(c.v===undefined||c.v===null||c.v==='');if(isEmpty){if(!hasStyle)return'';return`<c r="${c.ref}"${styleAttr}/>`;}if(typeof c.v==='number')return`<c r="${c.ref}"${styleAttr}><v>${c.v}</v></c>`;return`<c r="${c.ref}"${styleAttr} t="inlineStr"><is><t xml:space="preserve">${esc(c.v)}</t></is></c>`;}).join('');rowXmls.push(`<row r="${rowIdx}"${ht}>${cellXmls}</row>`);}const colsXml=cols.length?`<cols>${cols.map(c=>`<col min="${c.min}" max="${c.max}" width="${c.width}" customWidth="1"/>`).join('')}</cols>`:'';const mergeXml=merges.length?`<mergeCells count="${merges.length}">${merges.map(m=>`<mergeCell ref="${m}"/>`).join('')}</mergeCells>`:'';return`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">${colsXml}<sheetData>${rowXmls.join('')}</sheetData>${mergeXml}</worksheet>`;}
