function screensSheet({hasSelectionImg=false,hasAlvImg=false,alvStartRow=19,paramsStartRow=49}={}){const cells={},merges=[];const cols=[{min:1,max:1,width:3},{min:2,max:5,width:14},{min:6,max:6,width:50.71},{min:7,max:16,width:14},{min:17,max:17,width:3}];const rowHeights={1:30};screenFullRow(cells,merges,1,SHEET_TITLE,2);if(!hasSelectionImg&&SELECTION_IMAGE_SPEC)renderSelectionWireframe(cells,merges,rowHeights,3,SELECTION_IMAGE_SPEC);if(!hasAlvImg&&ALV_IMAGE_SPEC)renderAlvWireframe(cells,merges,rowHeights,alvStartRow,ALV_IMAGE_SPEC);let r=paramsStartRow;r=paramsBlock(cells,merges,rowHeights,r,SCREEN_PARAMS);if(Array.isArray(WARNINGS)&&WARNINGS.length){r+=1;rowHeights[r]=8;for(const msg of WARNINGS){r+=1;screenFullRow(cells,merges,r,String(msg),20);rowHeights[r]=WARNING_ROW_HEIGHT;}}return{cells,merges,cols,rowHeights};}
function sanitizeSheetName(name,seenNames){let n=String(name??'').replace(/[\\/?*\[\]]/g,'-').replace(/^'+|'+$/g,'');if(n.length>31)n=n.slice(0,31);if(!n)n='Sheet';let candidate=n,i=2;while(seenNames.has(candidate)){const suf=` (${i})`;candidate=n.slice(0,31-suf.length)+suf;i++;}seenNames.add(candidate);return candidate;}
function build(outPath,{images=[]}={}){const hasSelectionImg=images.some(img=>(img.anchorCell||'').toUpperCase()==='B3');const hasAlvImg=images.some(img=>(img.anchorCell||'').toUpperCase()==='B19');const DEFAULT_ROW_PX=20,IMG_GAP_PX=20,PARAMS_GAP_ROWS=2;const selImg=images.find(img=>(img.anchorCell||'').toUpperCase()==='B3');const alvImg=images.find(img=>(img.anchorCell||'').toUpperCase()==='B19');const selRowsSpan=selImg?Math.ceil((selImg.height+IMG_GAP_PX)/DEFAULT_ROW_PX):16;const alvStartRow=3+selRowsSpan;const alvRowsSpan=alvImg?Math.ceil((alvImg.height+IMG_GAP_PX)/DEFAULT_ROW_PX):13;const paramsStartRow=alvStartRow+alvRowsSpan+PARAMS_GAP_ROWS;if(alvImg)alvImg.anchorCell=`B${alvStartRow}`;const seen=new Set();const dataSheets=SHEETS_DATA.map(s=>{const payload=textSheet(s.rows,{colWidths:s.colWidths});if(s.name===PROCESS_FLOW_SHEET&&Array.isArray(PROCESS_FLOW)&&PROCESS_FLOW.length)appendProcessFlow(payload,PROCESS_FLOW,{heading:PROCESS_FLOW_HEADING});return{name:sanitizeSheetName(s.name,seen),payload};});const inputsSheet={name:sanitizeSheetName(INPUTS_SHEET_NAME,seen),payload:screensSheet({hasSelectionImg,hasAlvImg,alvStartRow,paramsStartRow})};const insertAt=Math.min(2,dataSheets.length);const sheets=[...dataSheets.slice(0,insertAt),inputsSheet,...dataSheets.slice(insertAt)];const validSheetNames=new Set(sheets.map(s=>s.name));const imagesBySheet=new Map();for(const img of images){const key=img.sheetName||INPUTS_SHEET_NAME;if(!validSheetNames.has(key)){console.warn(`[build] image sheetName "${key}" skipped`);continue;}if(!imagesBySheet.has(key))imagesBySheet.set(key,[]);imagesBySheet.get(key).push(img);}const drawings=[],mediaEntries=[];let drawingCounter=0,mediaCounter=0;sheets.forEach((s,idx)=>{const imgs=imagesBySheet.get(s.name);if(!imgs||!imgs.length)return;drawingCounter++;const wired=imgs.map((img,i)=>{mediaCounter++;const mediaName=`image${mediaCounter}.png`;mediaEntries.push({name:`xl/media/${mediaName}`,data:img.pngBuffer});return{...img,rid:`rId${i+1}`,mediaName};});drawings.push({drawingId:drawingCounter,sheetIdx:idx,imgs:wired});});const drawingIds=drawings.map(d=>d.drawingId);const hasPng=mediaEntries.length>0;const sheetXmls=sheets.map((s,idx)=>{let xmlStr=sheetXml(s.payload);const d=drawings.find(x=>x.sheetIdx===idx);if(d)xmlStr=injectDrawingRef(xmlStr);return{name:`xl/worksheets/sheet${idx+1}.xml`,data:Buffer.from(xmlStr,'utf8')};});const sheetRelEntries=drawings.map(d=>({name:`xl/worksheets/_rels/sheet${d.sheetIdx+1}.xml.rels`,data:Buffer.from(sheetDrawingRel(d.drawingId),'utf8')}));const drawingEntries=drawings.flatMap(d=>[{name:`xl/drawings/drawing${d.drawingId}.xml`,data:Buffer.from(drawingXml(d.imgs),'utf8')},{name:`xl/drawings/_rels/drawing${d.drawingId}.xml.rels`,data:Buffer.from(drawingRelsXml(d.imgs),'utf8')}]);const entries=[{name:'[Content_Types].xml',data:Buffer.from(contentTypes(sheets.length,{hasPng,drawingIds}),'utf8')},{name:'_rels/.rels',data:Buffer.from(rootRels(),'utf8')},{name:'xl/workbook.xml',data:Buffer.from(workbookXml(sheets.map(s=>s.name)),'utf8')},{name:'xl/_rels/workbook.xml.rels',data:Buffer.from(workbookRels(sheets.length),'utf8')},{name:'xl/styles.xml',data:Buffer.from(stylesXml(),'utf8')},...sheetXmls,...sheetRelEntries,...drawingEntries,...mediaEntries];writeFileSync(outPath,zipFiles(entries));console.log(`Wrote ${outPath} (${sheets.length} sheets${hasPng?`, ${mediaEntries.length} images`:''})`); }
function openInDefault(p){let cmd,args;if(platform()==='win32'){cmd='cmd.exe';args=['/c','start','""',p];}else if(platform()==='darwin'){cmd='open';args=[p];}else{cmd='xdg-open';args=[p];}spawn(cmd,args,{detached:true,stdio:'ignore',shell:false}).unref();}

async function buildImages(){if(!SELECTION_IMAGE_SPEC&&!ALV_IMAGE_SPEC)return[];try{const hereDir=dirname(fileURLToPath(import.meta.url));const candidates=[join(hereDir,'screen-image-renderer.mjs')];let cur=hereDir;for(let i=0;i<8;i++){candidates.push(join(cur,'scripts','spec','screen-image-renderer.mjs'));candidates.push(join(cur,'sc4sap','scripts','spec','screen-image-renderer.mjs'));const parent=dirname(cur);if(parent===cur)break;cur=parent;}candidates.push(join(process.cwd(),'scripts','spec','screen-image-renderer.mjs'));if(process.env.CLAUDE_PLUGIN_ROOT)candidates.push(join(process.env.CLAUDE_PLUGIN_ROOT,'scripts','spec','screen-image-renderer.mjs'));const rendererPath=candidates.find(p=>existsSync(p));if(!rendererPath){console.warn('[screen-images] renderer not found');return[];}const{renderScreenImages}=await import(pathToFileURL(rendererPath).href);const imgs=await renderScreenImages({selection:SELECTION_IMAGE_SPEC,alv:ALV_IMAGE_SPEC,lang:SPEC_LANG});const out=[];if(imgs.selection)out.push({sheetName:INPUTS_SHEET_NAME,anchorCell:'B3',pngBuffer:imgs.selection.pngBuffer,width:imgs.selection.width,height:imgs.selection.height});if(imgs.alv)out.push({sheetName:INPUTS_SHEET_NAME,anchorCell:'B19',pngBuffer:imgs.alv.pngBuffer,width:imgs.alv.width,height:imgs.alv.height});if(!out.length)console.warn('[screen-images] no browser — wireframe');return out;}catch(err){console.warn('[screen-images]',err?.message||err);return[];}}

const images=await buildImages();
build(OUT_PATH,{images});
openInDefault(OUT_PATH);

const CLEANUP_AFTER_BUILD=true;
if(CLEANUP_AFTER_BUILD&&existsSync(OUT_PATH)){try{const selfPath=fileURLToPath(import.meta.url);unlinkSync(selfPath);const dir=dirname(selfPath);if(dir.endsWith('_drivers')){try{const rem=readdirSync(dir).filter(f=>f!=='.'&&f!=='..');if(!rem.length)rmdirSync(dir);}catch{}}}catch(e){console.warn('[cleanup]',e?.message);}}

