1	// sc4sap:program-to-spec — Rich XLSX standalone driver TEMPLATE.
2	//
3	// Purpose:
4	//   Generate a human-readable multi-sheet .xlsx specification artifact
5	//   using REAL Excel cell geometry (styles.xml + borders + merged cells +
6	//   fixed column widths) — NOT ASCII box-drawing. ASCII art breaks when
7	//   Excel column widths don't match character widths; borders + merges
8	//   render cleanly at any zoom level.
9	//
10	// How the skill uses this file:
11	//   1. COPY this template to .sc4sap/specs/_drivers/{OBJECT}-{YYYYMMDD}.mjs
12	//      (or C:/Users/<user>/Desktop/... when the user specifies an absolute
13	//      directory).
14	//   2. REPLACE the three // TODO blocks:
15	//        - SHEETS_DATA    (text sheets — Overview, Data Model, Logic, ...)
16	//        - SCREEN_PARAMS  (Parameters table rendered under the wireframes)
17	//        - screensSheet() body (Dynpro + ALV wireframe using borders)
18	//      with the spec-specific content produced by sap-analyst + sap-writer.
19	//   3. SET OUT_PATH to the user's target file.
20	//   4. RUN `node <driver>.mjs`  → writes xlsx, auto-opens in default app.
21	//   5. DELETE the driver file on success. The xlsx is the artifact, the
22	//      driver is scaffolding.
23	//
24	// Zero npm dependencies — uses only node:zlib / node:fs / node:child_process.
25	
26	import { deflateRawSync } from 'node:zlib';
27	import { writeFileSync, existsSync, unlinkSync, readdirSync, rmdirSync } from 'node:fs';
28	import { spawn } from 'node:child_process';
29	import { platform } from 'node:os';
30	import { dirname, join, resolve } from 'node:path';
31	import { fileURLToPath, pathToFileURL } from 'node:url';
32	
33	// =============================================================
34	// ZIP + CRC32 (no external deps — XLSX is a zip of OOXML parts)
35	// =============================================================
36	const CRC_TABLE = (() => {
37	  const t = new Uint32Array(256);
38	  for (let n = 0; n < 256; n++) {
39	    let c = n;
40	    for (let k = 0; k < 8; k++) c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
41	    t[n] = c >>> 0;
42	  }
43	  return t;
44	})();
45	function crc32(buf) {
46	  let c = 0xffffffff;
47	  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
48	  return (c ^ 0xffffffff) >>> 0;
49	}
50	function u16(n) { const b = Buffer.alloc(2); b.writeUInt16LE(n, 0); return b; }
51	function u32(n) { const b = Buffer.alloc(4); b.writeUInt32LE(n >>> 0, 0); return b; }
52	
53	function zipFiles(entries) {
54	  const locals = [], centrals = [];
55	  let offset = 0;
56	  for (const e of entries) {
57	    const nameBuf = Buffer.from(e.name, 'utf8');
58	    const raw = e.data;
59	    const compressed = deflateRawSync(raw, { level: 9 });
60	    const useDeflate = compressed.length < raw.length;
61	    const body = useDeflate ? compressed : raw;
62	    const method = useDeflate ? 8 : 0;
63	    const crc = crc32(raw);
64	    const local = Buffer.concat([
65	      u32(0x04034b50), u16(20), u16(0x0800), u16(method),
66	      u16(0), u16(0), u32(crc), u32(body.length), u32(raw.length),
67	      u16(nameBuf.length), u16(0), nameBuf,
68	    ]);
69	    locals.push(local, body);
70	    const central = Buffer.concat([
71	      u32(0x02014b50), u16(20), u16(20), u16(0x0800), u16(method),
72	      u16(0), u16(0), u32(crc), u32(body.length), u32(raw.length),
73	      u16(nameBuf.length), u16(0), u16(0), u16(0), u16(0),
74	      u32(0), u32(offset), nameBuf,
75	    ]);
76	    centrals.push(central);
77	    offset += local.length + body.length;
78	  }
79	  const centralSize = centrals.reduce((s, p) => s + p.length, 0);
80	  const centralOffset = offset;
81	  const eocd = Buffer.concat([
82	    u32(0x06054b50), u16(0), u16(0),
83	    u16(entries.length), u16(entries.length),
84	    u32(centralSize), u32(centralOffset), u16(0),
85	  ]);
86	  return Buffer.concat([...locals, ...centrals, eocd]);
87	}
88	
89	// =============================================================
90	// XML helpers
91	// =============================================================
92	function esc(s) {
93	  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;')
94	    .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
95	}
96	function colLetter(c0) {
97	  let n = c0 + 1, s = '';
98	  while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); }
99	  return s;
100	}
101	const R = (r, c) => colLetter(c) + (r + 1);
102	
103	// =============================================================
104	// Styles catalog
105	//   Border slots (indices into BORDER_DEFS):
106	//     0 none | 1 all | 2 top | 3 bottom | 4 left | 5 right
107	//     6 TL  | 7 TR  | 8 BL  | 9 BR
108	//    10 TLR (top+left+right) | 11 LR | 12 BLR (bottom+left+right)
109	//
110	//   Fill slots:
111	//     0 none | 1 gray125 (OOXML default) | 2 light grey | 3 soft yellow
112	//     4 (RETIRED v8 — was light green; styles now point at fill 2 instead)
113	//     5 light sky blue (input widget — replaces grey for selection-screen params)
114	//
115	//   v8 palette rule (MANDATORY — propagated from SKILL.md):
116	//     · Headers / title bars / table captions → light grey (fill 2)
117	//     · Warnings / must-not-miss constraints → soft yellow (fill 3)
118	//     · Input widgets (selection-screen params) → light sky blue (fill 5)
119	//     · Do NOT reintroduce green. Grey + yellow is the whole palette.
120	//
121	//   Font slots:
122	//     0 default 11 Calibri | 1 bold 11 | 2 bold 14 | 3 bold 12
123	//
124	//   cellXfs (used via `s="N"` on each cell):
125	//     0 default          | 1 bold             | 2 report title (bold 14 center)
126	//     3 block title      | 4 ALV header       | 5 ALV data cell
127	//     6 input widget     | 7 label right      | 8 toolbar bold
128	//     9 left only        | 10 right only      | 11 top only
129	//    12 bottom only      | 13 TL              | 14 TR
130	//    15 BL               | 16 BR              | 17 frame-top TLR bold grey
131	//    18 all-border left  | 19 grey header     | 20 yellow highlight
132	//    21 bold bordered cell (for flow diagram nodes)
133	//    22 wrap (no border) | 23 wrap + border   | 24 wrap header (grey)
134	//    25 centered (no border, no fill) — flow-arrow rows ↓
135	// =============================================================
136	const BORDER_DEFS = [
137	  '<border><left/><right/><top/><bottom/><diagonal/></border>',
138	  '<border><left style="thin"><color rgb="FF000000"/></left><right style="thin"><color rgb="FF000000"/></right><top style="thin"><color rgb="FF000000"/></top><bottom style="thin"><color rgb="FF000000"/></bottom><diagonal/></border>',
139	  '<border><left/><right/><top style="thin"><color rgb="FF000000"/></top><bottom/><diagonal/></border>',
140	  '<border><left/><right/><top/><bottom style="thin"><color rgb="FF000000"/></bottom><diagonal/></border>',
141	  '<border><left style="thin"><color rgb="FF000000"/></left><right/><top/><bottom/><diagonal/></border>',
142	  '<border><left/><right style="thin"><color rgb="FF000000"/></right><top/><bottom/><diagonal/></border>',
143	  '<border><left style="thin"><color rgb="FF000000"/></left><right/><top style="thin"><color rgb="FF000000"/></top><bottom/><diagonal/></border>',
144	  '<border><left/><right style="thin"><color rgb="FF000000"/></right><top style="thin"><color rgb="FF000000"/></top><bottom/><diagonal/></border>',
145	  '<border><left style="thin"><color rgb="FF000000"/></left><right/><top/><bottom style="thin"><color rgb="FF000000"/></bottom><diagonal/></border>',
146	  '<border><left/><right style="thin"><color rgb="FF000000"/></right><top/><bottom style="thin"><color rgb="FF000000"/></bottom><diagonal/></border>',
147	  '<border><left style="thin"><color rgb="FF000000"/></left><right style="thin"><color rgb="FF000000"/></right><top style="thin"><color rgb="FF000000"/></top><bottom/><diagonal/></border>',
148	  '<border><left style="thin"><color rgb="FF000000"/></left><right style="thin"><color rgb="FF000000"/></right><top/><bottom/><diagonal/></border>',
149	  '<border><left style="thin"><color rgb="FF000000"/></left><right style="thin"><color rgb="FF000000"/></right><top/><bottom style="thin"><color rgb="FF000000"/></bottom><diagonal/></border>',
150	];
151	const CELL_XFS = [
152	  { },                                                                      // 0
153	  { font: 1 },                                                              // 1
154	  { font: 2, fill: 2, halign: 'center' },                                   // 2 sheet title — light grey (v7: was green) + bold 14
155	  { font: 3, fill: 2, border: 1, halign: 'center', valign: 'center' },      // 3 block title — light grey + bold (v8)
156	  { font: 1, fill: 2, border: 1, halign: 'center', valign: 'center' },      // 4 header row — light grey + bold (v8)
157	  { border: 1, halign: 'center', valign: 'center' },                        // 5
158	  { fill: 5, border: 1, halign: 'center' },                                 // 6 input widget — light sky blue + all borders
159	  { halign: 'right' },                                                      // 7
160	  { font: 1 },                                                              // 8
161	  { border: 4 },                                                            // 9  col-A left-only (v7: no fill, moved grey to style 2)
162	  { border: 5 },                                                            // 10 col-Q right-only
163	  { border: 2 },                                                            // 11
164	  { border: 3 },                                                            // 12
165	  { border: 6 },                                                            // 13 col-A TL (v7: no fill)
166	  { border: 7 },                                                            // 14
167	  { border: 8 },                                                            // 15 col-A BL (v7: no fill)
168	  { border: 9 },                                                            // 16 col-Q BR
169	  { border: 1, fill: 2, font: 1, halign: 'center' },                        // 17 frame-top — grey + bold + ALL borders (v8)
170	  { border: 1, halign: 'left', valign: 'center' },                          // 18
171	  { border: 1, halign: 'center', valign: 'center', font: 1, fill: 2 },      // 19 grey header (v8)
172	  { border: 1, fill: 3, halign: 'center', valign: 'center' },               // 20 yellow highlight
173	  { border: 1, font: 1, halign: 'center', valign: 'center' },               // 21 bold bordered (flow / toolbar boxes)
174	  { wrap: true, valign: 'top' },                                             // 22 wrap (no border)
175	  { border: 1, wrap: true, valign: 'top', halign: 'left' },                  // 23 wrap + border (long values)
176	  { border: 1, fill: 2, font: 1, wrap: true, halign: 'center', valign: 'center' }, // 24 wrap header — light grey (v8)
177	  { halign: 'center', valign: 'center' },                                    // 25 centered no-border no-fill — flow arrows
178	];
179	
180	function stylesXml() {
181	  const fonts = `<fonts count="4">
182	<font><sz val="11"/><name val="Calibri"/></font>
183	<font><b/><sz val="11"/><name val="Calibri"/></font>
184	<font><b/><sz val="14"/><name val="Calibri"/></font>
185	<font><b/><sz val="12"/><name val="Calibri"/></font>
186	</fonts>`;
187	  const fills = `<fills count="6">
188	<fill><patternFill patternType="none"/></fill>
189	<fill><patternFill patternType="gray125"/></fill>
190	<fill><patternFill patternType="solid"><fgColor rgb="FFE7E6E6"/><bgColor rgb="FFE7E6E6"/></patternFill></fill>
191	<fill><patternFill patternType="solid"><fgColor rgb="FFFFF2CC"/><bgColor rgb="FFFFF2CC"/></patternFill></fill>
192	<fill><patternFill patternType="solid"><fgColor rgb="FFE2EFDA"/><bgColor rgb="FFE2EFDA"/></patternFill></fill>
193	<fill><patternFill patternType="solid"><fgColor rgb="FFDDEBF7"/><bgColor rgb="FFDDEBF7"/></patternFill></fill>
194	</fills>`;
195	  const borders = `<borders count="${BORDER_DEFS.length}">${BORDER_DEFS.join('')}</borders>`;
196	  const xfs = CELL_XFS.map(x => {
197	    const attrs = [
198	      'numFmtId="0"',
199	      `fontId="${x.font || 0}"`,
200	      `fillId="${x.fill || 0}"`,
201	      `borderId="${x.border || 0}"`,
202	      'xfId="0"',
203	    ];
204	    if (x.font) attrs.push('applyFont="1"');
205	    if (x.fill) attrs.push('applyFill="1"');
206	    if (x.border) attrs.push('applyBorder="1"');
207	    if (x.halign || x.valign || x.wrap) attrs.push('applyAlignment="1"');
208	    const align = (x.halign || x.valign || x.wrap)
209	      ? `<alignment${x.halign ? ` horizontal="${x.halign}"` : ''}${x.valign ? ` vertical="${x.valign}"` : ''}${x.wrap ? ' wrapText="1"' : ''}/>`
210	      : '';
211	    return `<xf ${attrs.join(' ')}>${align}</xf>`;
212	  }).join('');
213	  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
214	<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
215	${fonts}
216	${fills}
217	${borders}
218	<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>
219	<cellXfs count="${CELL_XFS.length}">${xfs}</cellXfs>
220	<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>
221	</styleSheet>`;
222	}
223	
224	// =============================================================
225	// Sheet rendering:
226	//   Input shape:  { cells: {A1:{v,s}, ...}, merges:["A1:C1",...], cols:[{min,max,width}], rowHeights:{1:24} }
227	// =============================================================
228	function sheetXml({ cells, merges = [], cols = [], rowHeights = {} }) {
229	  const grouped = new Map();
230	  for (const [ref, c] of Object.entries(cells)) {
231	    const m = ref.match(/^([A-Z]+)(\d+)$/);
232	    const rowIdx = +m[2];
233	    if (!grouped.has(rowIdx)) grouped.set(rowIdx, []);
234	    grouped.get(rowIdx).push({ ref, ...c });
235	  }
236	  const rowXmls = [];
237	  for (const rowIdx of [...grouped.keys()].sort((a, b) => a - b)) {
238	    const cs = grouped.get(rowIdx).sort((a, b) => a.ref.localeCompare(b.ref, undefined, { numeric: true }));
239	    const ht = rowHeights[rowIdx] ? ` ht="${rowHeights[rowIdx]}" customHeight="1"` : '';
240	    const cellXmls = cs.map(c => {
241	      // Emit s="0" explicitly — style 0 (default) must not be dropped, else
242	      // a cell with style 0 and no value becomes a naked <c r="X"/> which
243	      // Excel flags as recoverable corruption.
244	      const hasStyle = (c.s !== undefined && c.s !== null);
245	      const styleAttr = hasStyle ? ` s="${c.s}"` : '';
246	      const isEmpty = (c.v === undefined || c.v === null || c.v === '');
247	      if (isEmpty) {
248	        // Skip entirely when neither style nor value — avoids <c r="X"/>.
249	        if (!hasStyle) return '';
250	        return `<c r="${c.ref}"${styleAttr}/>`;
251	      }
252	      if (typeof c.v === 'number') {
253	        return `<c r="${c.ref}"${styleAttr}><v>${c.v}</v></c>`;
254	      }
255	      return `<c r="${c.ref}"${styleAttr} t="inlineStr"><is><t xml:space="preserve">${esc(c.v)}</t></is></c>`;
256	    }).join('');
257	    rowXmls.push(`<row r="${rowIdx}"${ht}>${cellXmls}</row>`);
258	  }
259	  const colsXml = cols.length
260	    ? `<cols>${cols.map(c => `<col min="${c.min}" max="${c.max}" width="${c.width}" customWidth="1"/>`).join('')}</cols>`
261	    : '';
262	  const mergeXml = merges.length
263	    ? `<mergeCells count="${merges.length}">${merges.map(m => `<mergeCell ref="${m}"/>`).join('')}</mergeCells>`
264	    : '';
265	  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
266	<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
267	${colsXml}
268	<sheetData>${rowXmls.join('')}</sheetData>
