383	// =============================================================
384	// textSheet — auto-styles a 2D array of strings as a tabular sheet
385	//   (header row: bold + grey + all-borders; auto column widths)
386	//
387	// Use this for the DATA sheets (Overview, Data Model, Logic, Outputs,
388	// Authorization, Exceptions, Enhancements, Where-Used, etc.).
389	// =============================================================
390	// Visual width for column sizing — CJK / emoji / fullwidth count as 2
391	// because Calibri 11pt renders them ~2x the width of ASCII. Without this,
392	// Korean/Chinese/Japanese labels get truncated in auto-sized columns.
393	function visualWidth(s) {
394	  let w = 0;
395	  for (const ch of String(s ?? '')) {
396	    const cp = ch.codePointAt(0);
397	    if ((cp >= 0x1100 && cp <= 0x11FF) ||   // Hangul Jamo
398	        (cp >= 0x2E80 && cp <= 0x303F) ||   // CJK Radicals / Kangxi / Symbols
399	        (cp >= 0x3040 && cp <= 0x30FF) ||   // Hiragana + Katakana
400	        (cp >= 0x3400 && cp <= 0x9FFF) ||   // CJK Unified + Ext A
401	        (cp >= 0xAC00 && cp <= 0xD7AF) ||   // Hangul Syllables
402	        (cp >= 0xF900 && cp <= 0xFAFF) ||   // CJK Compat Ideographs
403	        (cp >= 0xFF00 && cp <= 0xFFEF) ||   // Fullwidth / Halfwidth
404	        cp >= 0x1F000) {                    // emoji + supplementary planes
405	      w += 2;
406	    } else {
407	      w += 1;
408	    }
409	  }
410	  return w;
411	}
412	
413	// ─── Auto-fit defaults (MUST NOT BE TIGHTENED) ────────────────────
414	// The program-to-spec skill requires that NO cell content is truncated
415	// in the rendered xlsx. These values are calibrated for Korean/CJK text
416	// in Calibri 11pt, with extra headroom for bold headers and merged
417	// labels. If a reviewer ever reports truncation, RAISE these — never
418	// lower them.
419	//
420	//   WIDTH_PADDING   = 6  breathing room beyond measured visual width
421	//                        (bold headers + CJK glyph drift need ≥ 4; use 6)
422	//   WIDTH_MIN       = 12 smallest usable col (single emoji + 1 char)
423	//   WIDTH_MAX       = 100 upper cap — beyond this, wrap saves horizontal
424	//                        screen real estate without clipping
425	//   WRAP_THRESHOLD  = 55 cells wider than this switch to wrapText +
426	//                        multi-line row height (≈ 2 Korean sentences)
427	const WIDTH_PADDING     = 6;
428	const WIDTH_MIN         = 12;
429	const WIDTH_MAX         = 100;
430	const WRAP_THRESHOLD    = 55;
431	const LINE_HEIGHT_PT    = 16.875; // per wrapped line — matches Google Sheets' xlsx baseline
432	                                  // (16.875 × 2 = 33.75, × 4 = 67.5 — the common 2-/4-line heights
433	                                  // produced when reviewers re-save in Sheets). v8 used 17 which
434	                                  // gave 34 / 68 — visually identical but didn't round-trip cleanly.
435	const HEADER_ROW_HEIGHT = 22.5;   // explicit row-1 height for bold header — gives the title row
436	                                  // breathing room above data, matches the reference reviewers expect.
437	const WARNING_ROW_HEIGHT = 22.5;  // sheet 3 yellow warning rows — same breathing room as headers.
438	const MAX_ROW_HEIGHT    = 300;    // row-height cap (some rules/long narratives need 5+ lines)
439	
440	// Row height per line count — Google Sheets uses inconsistent multipliers
441	// (16.875 for 2/4 lines, 17 for 3 lines). Single-multiplier formulas give
442	// 50.625 instead of 51 for 3-line rows. The lookup table reproduces REF
443	// exactly for 2-, 3-, 4-line cells; 5+ falls back to LINE_HEIGHT_PT × n.
444	const HEIGHT_BY_LINES = { 2: 33.75, 3: 51, 4: 67.5 };
445	function rowHeightForLines(n) {
446	  return HEIGHT_BY_LINES[n] ?? Math.min(n * LINE_HEIGHT_PT, MAX_ROW_HEIGHT);
447	}
448	
449	// textSheet(rows, opts) — opts.colWidths is an optional array of explicit column widths
450	// (in xlsx col-width units, e.g. 26, 145.71). When provided, auto-fit is bypassed and
451	// consecutive same-width entries are grouped (`<col min=4 max=6 width=12/>`). When omitted,
452	// the v4 CJK-aware auto-fit metric runs (WIDTH_MAX=100, WRAP_THRESHOLD=55).
453	//
454	// Use explicit colWidths when reverse-engineering a known reference (program-to-spec output
455	// must match the analyst's reviewed widths) — auto-fit is fine for greenfield specs.
456	function textSheet(rows, opts = {}) {
457	  const cells = {};
458	  const rowHeights = {};
459	  const maxCols = Math.max(...rows.map(r => r.length));
460	  const explicitWidths = Array.isArray(opts.colWidths) ? opts.colWidths : null;
461	
462	  // Pass 1a — ALWAYS compute auto-fit widths first (CJK-aware, capped at
463	  // WRAP_THRESHOLD). These drive ROW HEIGHT calculations even when the
464	  // emitted column widths are overridden via colWidths — this matches the
465	  // reference behavior where users widened specific columns in Sheets but
466	  // row heights kept their original "narrow column wrap" line counts. If
467	  // we computed row heights against the wide explicit widths, every long
468	  // cell would shrink to 2 lines and the spec would lose the visual rhythm
469	  // reviewers expect (220-char Note → 4 lines @ 67.5, not 2 @ 33.75).
470	  const autoCols = [];
471	  for (let c = 0; c < maxCols; c++) {
472	    let maxVw = 0;
473	    for (const row of rows) {
474	      const vw = visualWidth(row[c] ?? '');
475	      maxVw = Math.max(maxVw, Math.min(vw, WRAP_THRESHOLD));
476	    }
477	    const width = Math.min(Math.max(maxVw + WIDTH_PADDING, WIDTH_MIN), WIDTH_MAX);
478	    autoCols.push({ min: c + 1, max: c + 1, width });
479	  }
480	
481	  // Pass 1b — emitted cols. Use explicit widths when provided (with same-width
482	  // grouping). Auto-fit otherwise.
483	  let cols;
484	  if (explicitWidths) {
485	    cols = [];
486	    let i = 0;
487	    while (i < explicitWidths.length) {
488	      const w = explicitWidths[i];
489	      let j = i;
490	      while (j + 1 < explicitWidths.length && explicitWidths[j + 1] === w) j++;
491	      cols.push({ min: i + 1, max: j + 1, width: w });
492	      i = j + 1;
493	    }
494	    if (explicitWidths.length < maxCols) {
495	      cols.push({ min: explicitWidths.length + 1, max: maxCols, width: WIDTH_MIN });
496	    }
497	  } else {
498	    cols = autoCols;
499	  }
500	
501	  // Header row gets explicit breathing room (REF baseline). Data rows stay
502	  // at the workbook default (~15) unless they contain a "long" cell.
503	  if (rows.length > 0) rowHeights[1] = HEADER_ROW_HEIGHT;
504	
505	  // Pass 2 — emit cells, apply wrap style for long values, compute row heights
506	  // against AUTO-FIT widths so wraps match the reference cadence.
507	  rows.forEach((row, rIdx) => {
508	    let maxLines = 1;
509	    let anyLong = false;
510	    row.forEach((val, cIdx) => {
511	      const ref = R(rIdx, cIdx);
512	      const vw = visualWidth(val);
513	      const usable = Math.max(1, (autoCols[cIdx]?.width ?? WIDTH_MIN) - WIDTH_PADDING);
514	      const isLong = vw > WRAP_THRESHOLD;
515	      // Header row 0 → style 4 (bold grey border, non-wrap) for short headers,
516	      //                style 24 (wrap header) when long.
517	      // Data rows    → style 23 (wrap + border) when long, else style 18
518	      //                (all-border + left align). Every data cell gets a
519	      //                border so the spec reads as a uniform grid.
520	      const style = rIdx === 0
521	        ? (isLong ? 24 : 4)
522	        : (isLong ? 23 : 18);
523	      cells[ref] = { v: val, s: style };
524	      if (isLong) {
525	        anyLong = true;
526	        const lines = Math.ceil(vw / usable);
527	        if (lines > maxLines) maxLines = lines;
528	      }
529	    });
530	    if (rIdx > 0 && anyLong) {
531	      const lines = Math.max(2, maxLines);
532	      rowHeights[rIdx + 1] = rowHeightForLines(lines);
533	    }
534	  });
535	
536	  return { cells, merges: [], cols, rowHeights };
537	}
