987	// screensSheet — Inputs & Screens sheet body (v8).
988	//
989	// V8 SHEET ORDER (TOP → BOTTOM)
990	//   1. Sheet title                         style 2  (light grey, merged A:Q)
991	//   2. Image anchor rows                   blank rows where PNGs overlay
992	//        · Selection-screen image at B3   (driver-supplied anchor)
993	//        · ALV layout image at B{dyn}     (anchor row computed by build()
994	//                                          from the selection PNG's real
995	//                                          pixel height — legacy static
996	//                                          B19 overflowed for >5 fields)
997	//      Reserve those rows EMPTY in cells{}. buildImages() in build() lays
998	//      the PNG on top via oneCellAnchor.
999	//   3. Flow diagram (informational)        style 21 boxes, style 0 arrows
1000	//   4. BAPI / Action mapping (informational) style 18 cells, no heavy fill
1001	//   5. Parameters table                    paramsBlock() — header style 4,
1002	//                                          data style 5 (grey header only)
1003	//   6. Yellow warnings                     MUST be at the BOTTOM of the sheet
1004	//        · Authority / Auth-check caveats  style 20, merged A:Q
1005	//        · Data-volume / runtime caveats   style 20, merged A:Q
1006	//      Rationale: readers scan top→bottom; constraints sit last so the
1007	//      positive content (screens + parameters) isn't drowned in warnings.
1008	//
1009	// V8 COLOR RULES
1010	//   · Headers / title bars / table captions → GREY (fill 2) — NEVER green.
1011	//   · Warnings (must-not-miss) → YELLOW (fill 3), style 20.
1012	//   · Input widgets on wireframe → SKY BLUE (fill 5), style 6.
1013	//   · Informational rows (flow, BAPI) → NO FILL beyond optional grey header.
1014	//     Keep them uncluttered — the images carry the visual weight.
1015	//
1016	// V8 IMAGE PIPELINE (see scripts/spec/screen-image-renderer.mjs)
1017	//   const { renderScreenImages } = await import('./screen-image-renderer.mjs');
1018	//   const imgs = await renderScreenImages({
1019	//     selection: { fields: [...], optionFields: [...] },
1020	//     alv:       { columns: [...], sampleRows: [...], maxRows: 3 },
1021	//   });
