1024	//   if (imgs.selection) images.push({ sheetName: INPUTS_SHEET_NAME, anchorCell: 'B3',
1025	//                                     pngBuffer: imgs.selection.pngBuffer,
1026	//                                     width: imgs.selection.width, height: imgs.selection.height });
1027	//   if (imgs.alv)       images.push({ sheetName: INPUTS_SHEET_NAME, anchorCell: 'B19',
1028	//                                     pngBuffer: imgs.alv.pngBuffer,
1029	//                                     width: imgs.alv.width, height: imgs.alv.height });
1030	//   build(OUT_PATH, { images });
1031	//
1032	//   ALV sample rows MUST be capped at 3 (up to 5 when showing lock/edit/mixed-
1033	//   status variants). Never emit >5 — a mockup, not a data dump.
1034	//
1035	//   If imgs.selection / imgs.alv is null (no headless browser), fall back
1036	//   to the legacy cell-border wireframe via screenFullRow / screenMerge
1037	//   helpers — DO NOT silently omit the screens.
1038	//
1039	// LAYOUT GRID (17-col)
1040	//   A=3, B..P=14 each, Q=3. Max full-width merge = A:Q.
1041	//
1042	// RETURN SHAPE
1043	//   { cells, merges, cols, rowHeights }
1044	// =============================================================
1045	function screensSheet({
1046	  hasSelectionImg = false,
1047	  hasAlvImg = false,
1048	  alvStartRow = 19,        // Dynamically computed by build() from selection PNG height.
1049	  paramsStartRow = 49,     // Dynamically computed by build() from ALV PNG height.
1050	} = {}) {
1051	  const cells = {};
1052	  const merges = [];
1053	  // Col F (col 6) is widened so the Parameters table's Type column (E:F merge)
1054	  // can show full SELECT-OPTIONS / DDIC type strings without clipping
1055	  // (e.g. "SELECT-OPTIONS → VBAK-VKORG (VKORG CHAR4)" — 40 chars). Other B..P
1056	  // cols stay at 14 to preserve the selection-screen widget grid (B:E label,
1057	  // F:H low input, K:M high input). The fallback wireframe's F:H low-input
1058	  // merge becomes lopsided (50.71 + 14 + 14 = 78.71 vs K:M 42), but PNG embed
1059	  // is the v8.1+ primary path so the wireframe is rarely seen.
1060	  const cols = [
1061	    { min: 1, max: 1,  width: 3      },
1062	    { min: 2, max: 5,  width: 14     },
1063	    { min: 6, max: 6,  width: 50.71  },
1064	    { min: 7, max: 16, width: 14     },
1065	    { min: 17, max: 17, width: 3     },
1066	  ];
1067	  const rowHeights = { 1: 30 };
1068	
1069	  // Row 1 — sheet title (always rendered, grey style 2, merged A:Q).
1070	  screenFullRow(cells, merges, 1, SHEET_TITLE, 2);
1071	
1072	  // Selection area — starts at row 3.
1073	  //   · PNG overlay when hasSelectionImg (leave cells blank so image is visible).
1074	  //   · Cell-border wireframe when SELECTION_IMAGE_SPEC present but no image.
1075	  //   · Blank when spec is null (object has no selection screen).
1076	  if (!hasSelectionImg && SELECTION_IMAGE_SPEC) {
1077	    renderSelectionWireframe(cells, merges, rowHeights, 3, SELECTION_IMAGE_SPEC);
1078	  }
1079	
1080	  // ALV area — starts at alvStartRow (dynamic; defaults to 19 for wireframe).
1081	  if (!hasAlvImg && ALV_IMAGE_SPEC) {
1082	    renderAlvWireframe(cells, merges, rowHeights, alvStartRow, ALV_IMAGE_SPEC);
1083	  }
1084	
1085	  // Flow diagram / BAPI mapping rows: drivers may add additional content
1086	  // between ALV and Parameters via a post-build edit.
1087	
1088	  // Parameters table — grey header, full-bordered data rows.
1089	  let r = paramsStartRow;
1090	  r = paramsBlock(cells, merges, rowHeights, r, SCREEN_PARAMS);
1091	
1092	  // WARNINGS — MUST be the last content on the sheet (v8 rule). Rendered
1093	  // automatically from the top-level WARNINGS constant so every spec that
1094	  // populates it gets consistent yellow bottom rows without driver copies
1095	  // needing to call screenFullRow(...) by hand. Empty WARNINGS = no rows.
1096	  if (Array.isArray(WARNINGS) && WARNINGS.length) {
1097	    r += 1;                 // one blank spacer row below Parameters
1098	    rowHeights[r] = 8;      // slim spacer so the warning block stays close
1099	    for (const msg of WARNINGS) {
1100	      r += 1;
1101	      screenFullRow(cells, merges, r, String(msg), 20);
1102	      rowHeights[r] = WARNING_ROW_HEIGHT;
1103	    }
1104	  }
1105	
1106	  return { cells, merges, cols, rowHeights };
1107	}
