1139	//   Each entry is a single plain-text string (A:Q merged, style 20 yellow).
1140	//   Prefix with ⚠ so the row is scannable. Examples:
1141	//     '⚠ Authorization (GAP): No AUTHORITY-CHECK — add V_VBAK_VKO for row-level.'
1142	//     '⚠ Runtime: 4-way JOIN returns cartesian item×header rows; keep VKORG + date tight.'
1143	//     '⚠ PII: KNA1~NAME1 exposed in output; mask for non-SD audiences.'
1144	// =============================================================
1145	const WARNINGS = [];
1146	
1147	// =============================================================
1148	// Build + auto-open
1149	// =============================================================
1150	// Excel sheet name rules (enforced here so a typo in SHEETS_DATA doesn't
1151	// produce a file that opens with a "recovered contents" dialog):
1152	//   · Forbidden characters: \ / ? * [ ]
1153	//   · Max length: 31 characters
1154	//   · Must not be blank; must not start/end with apostrophe
1155	//   · Must be unique within the workbook
1156	function sanitizeSheetName(name, seenNames) {
1157	  let n = String(name ?? '').replace(/[\\/?*\[\]]/g, '-');
1158	  n = n.replace(/^'+|'+$/g, '');
1159	  if (n.length > 31) n = n.slice(0, 31);
1160	  if (!n) n = 'Sheet';
1161	  let candidate = n, i = 2;
1162	  while (seenNames.has(candidate)) {
1163	    const suffix = ` (${i})`;
1164	    candidate = n.slice(0, 31 - suffix.length) + suffix;
1165	    i++;
1166	  }
1167	  seenNames.add(candidate);
1168	  return candidate;
1169	}
1170	
1171	// build({ outPath, images })
1172	//   images — optional array from screen-image-renderer.renderScreenImages():
1173	//     [{ sheetName, pngBuffer, anchorCell:'B3', width, height }, ...]
1174	//   Anchor cell is on the target sheet (usually INPUTS_SHEET_NAME).
1175	//   Omit or pass [] → v8 degrades gracefully to cell-border wireframes.
1176	function build(outPath, { images = [] } = {}) {
1177	  // Pre-analyse image anchors so screensSheet() knows whether to skip the
1178	  // cell-border wireframe (image will overlay) or draw it (no image for
1179	  // that section, so readers still see the layout).
1180	  //
1181	  // Drivers hand us images with two sentinel anchors:
1182	  //   · 'B3'  → selection-screen PNG
1183	  //   · 'B19' → ALV layout PNG
1184	  // The B19 sentinel is the ORIGINAL (static) anchor from v8.0. We keep
1185	  // matching on it here because it's the contract with buildImages() /
1186	  // external drivers. The anchor is REWRITTEN below once we know the real
1187	  // selection image height.
1188	  const hasSelectionImg = images.some(img => (img.anchorCell || '').toUpperCase() === 'B3');
1189	  const hasAlvImg       = images.some(img => (img.anchorCell || '').toUpperCase() === 'B19');
1190	
1191	  // ── Dynamic anchor layout (v8.2 fix) ──────────────────────────
1192	  // The selection PNG height is a function of field count:
1193	  //   renderSelectionScreenSVG: h = 40 + N*24 + 60 + (M ? 24+M*24 : 0) + 60
1194	  // so it easily exceeds the 16-row (≈320 px @ default row height 15 pt)
1195	  // span that the legacy static anchor B3→B19 assumed. Anything beyond
1196	  // ~5 fields + 1 option (the smoke case, 328 px) spills into the B19
1197	  // anchor row and the later-drawn ALV image paints on top, visually
1198	  // cropping the bottom of the selection image.
1199	  // Fix: read each image's actual pixel height and place the ALV anchor
1200	  // (and the Parameters table below it) at computed rows so there is
1201	  // never any overlap, regardless of how many fields / option-fields the
1202	  // selection screen has.
1203	  const DEFAULT_ROW_PX = 20;     // Excel default row height (15 pt @ 96 DPI).
1204	  const IMG_GAP_PX = 20;         // One-row visual gap below each image.
1205	  const PARAMS_GAP_ROWS = 2;     // Breathing room between ALV block and Parameters table.
1206	  const selImg = images.find(img => (img.anchorCell || '').toUpperCase() === 'B3');
1207	  const alvImg = images.find(img => (img.anchorCell || '').toUpperCase() === 'B19');
1208	  // Rows the selection image (or wireframe) occupies, starting at row 3.
1209	  // If selection is absent we fall back to the legacy 16-row span so
1210	  // wireframe-only / alv-only specs keep their original layout.
1211	  const selRowsSpan = selImg ? Math.ceil((selImg.height + IMG_GAP_PX) / DEFAULT_ROW_PX) : 16;
1212	  const alvStartRow = 3 + selRowsSpan;
1213	  // Rows the ALV image (or wireframe) occupies.
1214	  const alvRowsSpan = alvImg ? Math.ceil((alvImg.height + IMG_GAP_PX) / DEFAULT_ROW_PX) : 13;
1215	  // Parameters table sits right under the ALV block with a small breathing
1216	  // gap — no lower clamp. The legacy row-49 minimum was reserving space for
1217	  // an optional flow-diagram / BAPI-mapping block between ALV and Params,
1218	  // but that region is not emitted by any current driver, so clamping
1219	  // produces a large blank stretch for every spec. Drivers that really need
1220	  // that reserve can widen PARAMS_GAP_ROWS or append content after build().
1221	  const paramsStartRow = alvStartRow + alvRowsSpan + PARAMS_GAP_ROWS;
1222	  // Rewrite ALV anchor in place so drawingXml() emits the computed cell.
1223	  if (alvImg) alvImg.anchorCell = `B${alvStartRow}`;
1224	
1225	  const seen = new Set();
1226	  const dataSheets = SHEETS_DATA.map(s => {
1227	    // textSheet honours per-sheet colWidths when the driver supplies them
1228	    // (used to round-trip a known reference file's column widths exactly).
1229	    const payload = textSheet(s.rows, { colWidths: s.colWidths });
1230	    // Auto-attach the process flowchart under the Processing Logic sheet
1231	    // (or whichever sheet the driver names as PROCESS_FLOW_SHEET). Empty
1232	    // PROCESS_FLOW = no-op, so other sheets pass through untouched.
1233	    if (s.name === PROCESS_FLOW_SHEET && Array.isArray(PROCESS_FLOW) && PROCESS_FLOW.length) {
1234	      appendProcessFlow(payload, PROCESS_FLOW, { heading: PROCESS_FLOW_HEADING });
1235	    }
1236	    return { name: sanitizeSheetName(s.name, seen), payload };
1237	  });
1238	  const inputsSheet = {
1239	    name: sanitizeSheetName(INPUTS_SHEET_NAME, seen),
1240	    payload: screensSheet({ hasSelectionImg, hasAlvImg, alvStartRow, paramsStartRow }),
1241	  };
1242	  const insertAt = Math.min(2, dataSheets.length);
1243	  const sheets = [
1244	    ...dataSheets.slice(0, insertAt),
1245	    inputsSheet,
1246	    ...dataSheets.slice(insertAt),
1247	  ];
1248	
1249	  // Validate image sheetName against actual workbook sheets. Silent drop
1250	  // was a pre-v8 bug: drivers that localised INPUTS_SHEET_NAME (e.g.
1251	  // '입력 및 화면') but left images[].sheetName as 'Inputs & Screens'
1252	  // used to lose the PNGs with no log at all. Now we warn + skip that one
1253	  // image, and other sheets continue rendering normally.
1254	  const validSheetNames = new Set(sheets.map(s => s.name));
1255	  const imagesBySheet = new Map();
1256	  for (const img of images) {
1257	    const key = img.sheetName || INPUTS_SHEET_NAME;
1258	    if (!validSheetNames.has(key)) {
1259	      console.warn(`[build] image sheetName "${key}" not in workbook sheets [${[...validSheetNames].join(', ')}] — image skipped. Did you localise INPUTS_SHEET_NAME but forget to update images[].sheetName?`);
1260	      continue;
1261	    }
1262	    if (!imagesBySheet.has(key)) imagesBySheet.set(key, []);
1263	    imagesBySheet.get(key).push(img);
1264	  }
1265	
1266	  // Assign drawing/media IDs deterministically.
1267	  const drawings = [];      // [{ drawingId, sheetIdx, imgs:[{ rid, mediaName, ... }] }]
1268	  const mediaEntries = [];  // [{ name, data }]
1269	  let drawingCounter = 0, mediaCounter = 0;
1270	  sheets.forEach((s, idx) => {
1271	    const imgs = imagesBySheet.get(s.name);
1272	    if (!imgs || !imgs.length) return;
1273	    drawingCounter++;
1274	    const wired = imgs.map((img, i) => {
1275	      mediaCounter++;
1276	      const mediaName = `image${mediaCounter}.png`;
1277	      mediaEntries.push({ name: `xl/media/${mediaName}`, data: img.pngBuffer });
1278	      return { ...img, rid: `rId${i + 1}`, mediaName };
1279	    });
1280	    drawings.push({ drawingId: drawingCounter, sheetIdx: idx, imgs: wired });
1281	  });
1282	
1283	  const drawingIds = drawings.map(d => d.drawingId);
1284	  const hasPng = mediaEntries.length > 0;
1285	
1286	  // Build worksheet XMLs — inject <drawing> ref on sheets that have one.
1287	  const sheetXmls = sheets.map((s, idx) => {
1288	    let xmlStr = sheetXml(s.payload);
1289	    const d = drawings.find(x => x.sheetIdx === idx);
1290	    if (d) xmlStr = injectDrawingRef(xmlStr);
1291	    return { name: `xl/worksheets/sheet${idx + 1}.xml`, data: Buffer.from(xmlStr, 'utf8') };
1292	  });
1293	
1294	  // Per-sheet rels (only for sheets with drawings).
1295	  const sheetRelEntries = drawings.map(d => ({
1296	    name: `xl/worksheets/_rels/sheet${d.sheetIdx + 1}.xml.rels`,
1297	    data: Buffer.from(sheetDrawingRel(d.drawingId), 'utf8'),
1298	  }));
1299	
1300	  // Drawing parts + their rels.
1301	  const drawingEntries = drawings.flatMap(d => [
1302	    { name: `xl/drawings/drawing${d.drawingId}.xml`, data: Buffer.from(drawingXml(d.imgs), 'utf8') },
1303	    { name: `xl/drawings/_rels/drawing${d.drawingId}.xml.rels`, data: Buffer.from(drawingRelsXml(d.imgs), 'utf8') },
1304	  ]);
1305	
1306	  const entries = [
1307	    { name: '[Content_Types].xml', data: Buffer.from(contentTypes(sheets.length, { hasPng, drawingIds }), 'utf8') },
1308	    { name: '_rels/.rels', data: Buffer.from(rootRels(), 'utf8') },
1309	    { name: 'xl/workbook.xml', data: Buffer.from(workbookXml(sheets.map(s => s.name)), 'utf8') },
1310	    { name: 'xl/_rels/workbook.xml.rels', data: Buffer.from(workbookRels(sheets.length), 'utf8') },
1311	    { name: 'xl/styles.xml', data: Buffer.from(stylesXml(), 'utf8') },
1312	    ...sheetXmls,
1313	    ...sheetRelEntries,
1314	    ...drawingEntries,
1315	    ...mediaEntries,
1316	  ];
1317	  writeFileSync(outPath, zipFiles(entries));
1318	  console.log(`Wrote ${outPath} (${sheets.length} sheets${hasPng ? `, ${mediaEntries.length} images` : ''})`);
1319	}
1320	function openInDefault(p) {
1321	  let cmd, args;
1322	  if (platform() === 'win32') { cmd = 'cmd.exe'; args = ['/c', 'start', '""', p]; }
1323	  else if (platform() === 'darwin') { cmd = 'open'; args = [p]; }
1324	  else { cmd = 'xdg-open'; args = [p]; }
1325	  const child = spawn(cmd, args, { detached: true, stdio: 'ignore', shell: false });
1326	  child.unref();
1327	}
1328	
1329	// =============================================================
1330	// V8 AUTO-IMAGE PIPELINE
1331	//
1332	// Drivers DO NOT need to import renderScreenImages — just populate
1333	// SELECTION_IMAGE_SPEC / ALV_IMAGE_SPEC at the top of this file. This
1334	// helper calls into screen-image-renderer.mjs which renders Selection +
1335	// ALV as PNG IN PARALLEL (Promise.all → concurrent headless browsers).
1336	//
1337	// Universal applicability: this path runs for EVERY xlsx spec regardless
1338	// of language (ko/en/ja/de/…) and depth (L1/L2/L3/L4). The only hard
1339	// requirements are (a) format=xlsx and (b) at least one of the two specs
1340	// is populated.
1341	//
1342	// Returns an empty [] when either:
1343	//   · Both specs are null (object has no UI — e.g. pure FM / CDS / RAP
1344	//     without screens), OR
1345	//   · No headless browser is installed (Edge / Chrome / Chromium not
1346	//     found on PATH / standard install dirs).
1347	// In both cases screensSheet() auto-draws cell-border wireframes for
1348	// whichever SPEC is populated — readers still see the layout.
1349	// =============================================================
1350	async function buildImages() {
1351	  if (!SELECTION_IMAGE_SPEC && !ALV_IMAGE_SPEC) return [];
1352	  try {
1353	    // Resolve screen-image-renderer.mjs. Works whether this file runs in
1354	    // its original location (scripts/spec/...) OR was copied as a
1355	    // throwaway per-spec driver to .sc4sap/specs/_drivers/, to an absolute
1356	    // Desktop folder, or into a plugin cache. Search order:
1357	    //   (1) next to this file                          → in-place / plugin cache
1358	    //   (2) walk up + 'scripts/spec/...'               → consumer layout (scripts/ at root)
1359	    //   (3) walk up + 'sc4sap/scripts/spec/...'        → plugin-dev layout (source inside sc4sap/)
1360	    //   (4) process.cwd() + 'scripts/spec/...'         → invocation from project root, consumer
1361	    //   (5) process.cwd() + 'sc4sap/scripts/spec/...'  → invocation from project root, dev
1362	    //   (6) CLAUDE_PLUGIN_ROOT env (Claude Code plugin cache runtime)
1363	    const hereDir = dirname(fileURLToPath(import.meta.url));
1364	    const candidates = [join(hereDir, 'screen-image-renderer.mjs')];
1365	    let cur = hereDir;
1366	    for (let i = 0; i < 8; i++) {
1367	      candidates.push(join(cur, 'scripts', 'spec', 'screen-image-renderer.mjs'));
1368	      candidates.push(join(cur, 'sc4sap', 'scripts', 'spec', 'screen-image-renderer.mjs'));
1369	      const parent = dirname(cur);
1370	      if (parent === cur) break;
1371	      cur = parent;
1372	    }
1373	    candidates.push(join(process.cwd(), 'scripts', 'spec', 'screen-image-renderer.mjs'));
1374	    candidates.push(join(process.cwd(), 'sc4sap', 'scripts', 'spec', 'screen-image-renderer.mjs'));
1375	    if (process.env.CLAUDE_PLUGIN_ROOT) {
1376	      candidates.push(join(process.env.CLAUDE_PLUGIN_ROOT, 'scripts', 'spec', 'screen-image-renderer.mjs'));
1377	    }
1378	    const rendererPath = candidates.find(p => existsSync(p));
1379	    if (!rendererPath) {
1380	      console.warn('[screen-images] screen-image-renderer.mjs not resolvable — falling back to wireframe. Searched:\n  - ' + candidates.slice(0, 8).join('\n  - '));
1381	      return [];
1382	    }
1383	    const { renderScreenImages } = await import(pathToFileURL(rendererPath).href);
1384	    const imgs = await renderScreenImages({
1385	      selection: SELECTION_IMAGE_SPEC,
1386	      alv: ALV_IMAGE_SPEC,
1387	      lang: SPEC_LANG,
1388	    });
1389	    const out = [];
1390	    if (imgs.selection) out.push({
1391	      sheetName: INPUTS_SHEET_NAME, anchorCell: 'B3',
1392	      pngBuffer: imgs.selection.pngBuffer,
1393	      width: imgs.selection.width, height: imgs.selection.height,
1394	    });
1395	    if (imgs.alv) out.push({
1396	      sheetName: INPUTS_SHEET_NAME, anchorCell: 'B19',
1397	      pngBuffer: imgs.alv.pngBuffer,
1398	      width: imgs.alv.width, height: imgs.alv.height,
1399	    });
1400	    if (!out.length) {
1401	      console.warn('[screen-images] headless browser unavailable — cell-border wireframe will be used instead');
1402	    }
1403	    return out;
1404	  } catch (err) {
1405	    console.warn('[screen-images] renderer error:', err?.message || err, '— falling back to wireframe');
1406	    return [];
1407	  }
1408	}
1409	
1410	const images = await buildImages();
1411	build(OUT_PATH, { images });
1412	openInDefault(OUT_PATH);
1413	
1414	// =============================================================
1415	// Self-cleanup (v8.3)
1416	//
1417	// The driver is SCAFFOLDING — once the xlsx is written and verified,
1418	// keeping the per-spec .mjs file around just clutters the repo and
1419	// confuses future readers into thinking it's part of the deliverable.
1420	// We self-delete at the end of a SUCCESSFUL run (build() didn't throw,
1421	// so OUT_PATH exists) to guarantee cleanup regardless of whether the
1422	// calling agent remembers to `rm` it.
1423	//
1424	// Safety guards:
1425	//   · Only runs if CLEANUP_AFTER_BUILD is true (set false for debugging
1426	//     a failed/weird render — then you can edit+rerun the same driver).
1427	//   · Only runs if OUT_PATH actually exists (build could have silently
1428	//     bailed — don't self-destruct without evidence of success).
1429	//   · Only deletes the driver FILE itself, plus its enclosing directory
1430	//     if that directory (a) is `_drivers`, (b) becomes empty after we
1431	//     remove the driver. We never rmdir a user-supplied absolute path
1432	//     like `C:\Users\me\Desktop\test\` even if it ends up empty.
1433	//   · Any error (file locked, permission, antivirus) is logged as warn
1434	//     and swallowed — the xlsx artifact still survives, user can rm
1435	//     the driver by hand.
1436	// =============================================================
1437	const CLEANUP_AFTER_BUILD = true;
1438	if (CLEANUP_AFTER_BUILD) {
1439	  try {
1440	    if (!existsSync(resolve(OUT_PATH))) {
1441	      console.warn('[cleanup] skipped: OUT_PATH not found on disk — keeping driver for debugging.');
1442	    } else {
1443	      const driverPath = fileURLToPath(import.meta.url);
1444	      const driverDir = dirname(driverPath);
1445	      unlinkSync(driverPath);
1446	      console.log(`[cleanup] removed driver: ${driverPath}`);
1447	      // Best-effort rmdir of the scaffolding folder when it only existed
1448	      // to hold this driver. Scope the cleanup to folders literally named
1449	      // `_drivers` so we never delete an arbitrary user directory.
1450	      if (driverDir.endsWith('_drivers') || driverDir.endsWith('\\_drivers') || driverDir.endsWith('/_drivers')) {
1451	        try {
1452	          const remaining = readdirSync(driverDir);
1453	          if (remaining.length === 0) {
1454	            rmdirSync(driverDir);
1455	            console.log(`[cleanup] removed empty _drivers folder: ${driverDir}`);
1456	          }
1457	        } catch { /* non-empty or race — leave it */ }
1458	      }
1459	    }
1460	  } catch (err) {
1461	    console.warn(`[cleanup] driver self-delete failed: ${err?.message || err}`);
1462	    console.warn(`[cleanup] remove the driver manually when convenient.`);
1463	  }
1464	}
